\label{thm:wellposedness_Whitham}
    Let $s > \frac{13}{8}$, $\epsilon,\mu \in (0,1]$, and $\eta_0 \in H^s(\mathbb{R})$.  Then there exists a positive time
    \begin{align} \label{T_eps_mu}
        T_{\epsilon,\mu}= c^{-1} \epsilon^{-1} \Big(\frac{\mu}{\epsilon}\Big)^{\frac{1}{4}^-} (\lVert\eta_0\rVert_{H^s_x})^{(-\frac{5}{4})^+} 
    \end{align}
    such that \eqref{eq:Whitham} has a unique solution 
    \begin{align*}
       \eta \in C([0,T_{\epsilon,\mu}];H^s(\mathbb{R})) \cap C^1([0,T_{\epsilon,\mu}];H^{s-1}(\mathbb{R}))
    \end{align*}
    satisfying the initial condition $\eta(0) = \eta_0$. Moreover,
    \begin{align*}
        \sup_{t\in[0,T_{\epsilon,\mu}]} \lVert\eta(t)\rVert_{H^s_x} \lesssim \lVert\eta_0\rVert_{H^s_x}.  
    \end{align*}
    Further, there exists a neighborhood $\mathcal{U}$ of $\eta_0$ in $H^s(\mathbb{R})$ such that the flow map
    \begin{align*}
        F_{\epsilon,\mu} : \mathcal{U} \rightarrow C([0,\frac{T_{\epsilon,\mu}}{2}];H^s(\mathbb{R})), \ \ \ \ \eta_0 \mapsto \eta
    \end{align*}
    is continuous.

Let $d\in \{1,2\}$,  $s>\frac{d}{2}$, and $\epsilon\in (0,1]$. We say that the initial surface elevation $\eta_0 \in H^s(\mathbb{R}^d)$ satisfies the \textit{non-cavitation condition} if there exists a constant $h_0 \in (0,1)$ such that 
    \begin{align}\label{eq:noncav}
        1 + \epsilon\eta_0(x) \geq h_0
    \end{align}
    for all $x \in \mathbb{R}^d$.

\label{def:solution_space}
    We define the solution space $V_\mu^s(\mathbb{R}^d)$ via the norm
    \begin{align*}
        \lVert(\eta,\mathbf{v})\rVert_{V_\mu^s}^2  := \lVert\eta\rVert_{H^s_x}^2 + \lVert\mathbf{v}\rVert_{H^s_x}^2 + \sqrt{\mu} \lVert|D|^\frac{1}{2} \mathbf{v}\rVert_{H^s_x}^2.
    \end{align*}

We observe that 
    \begin{align}\label{eq:equivalent_norm_Vsmu}
        \lVert(\eta,\mathbf{v})\rVert_{V_\mu^s}^2 \sim  \lVert\eta\rVert_{H^s_x}^2 + \lVert\mathcal{T}_\mu^{-\frac{1}{2}}(D) \mathbf{v}\rVert_{H^s_x}^2
    \end{align}
    (see \cite[Corollary 2.6]{Paulsen2022}).

\label{thm:wellposedness_WB}
    Let $d\in \{1,2\}$,  $s>1+\frac{5d}{8}$,
        and $\epsilon,\mu \in (0,1]$. Assume that the initial data $(\eta_0,\mathbf{v}_0) \in V^s_\mu(\mathbb{R}^d)$ 
    satisfy \eqref{eq:noncav} and that $\mathrm{curl}\:\mathbf{v}_0=0$ if $d=2$. Then there exists a positive time
    \begin{equation}\label{WBtime}
        T_{\epsilon,\mu,d}= c^{-1}\epsilon^{-\frac{d+3}{4}} \Big(\frac{\mu}{\epsilon}\Big)^{\frac{1}{4}^-} (\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu})^{(-\frac{d+4}{4})^+},
    \end{equation}
    for some $c=c\bigl(d,s,h_0, 1+\epsilon\lVert(\eta_0,\mathbf{v}_0)\rVert_{L^\infty_x\times L^\infty_x}\bigr) > 0$,
    such that \eqref{eq:whitham_boussinesq} and \eqref{eq:whitham_boussinesq_d2} admits a unique solution 
    \begin{align*}
        (\eta,\mathbf{v}) \in C([0,T_{\epsilon,\mu,d}];V_\mu^s(\mathbb{R}^d)) \cap C^1([0,T_{\epsilon,\mu,d}];V_\mu^{s-1}(\mathbb{R}^d))
    \end{align*}
    satisfying the initial conditions $\eta(0) = \eta_0$ and $\mathbf v(0) = \mathbf v_0$. Moreover,
    \begin{align*}
        \sup_{t\in[0,T_{\epsilon,\mu,d}]} \lVert(\eta,\mathbf{v})(t)\rVert_{V_\mu^s} \lesssim \lVert(\eta_0,\mathbf{v}_0)\rVert_{V_\mu^s},
    \end{align*}
    where the implicit constant may depend on the non-cavitation parameter $h_0$ and $1+\epsilon\lVert(\eta_0,\mathbf{v}_0)\rVert_{L^\infty_x\times L^\infty_x}$. Furthermore, the flow map depends continuously on the initial data.

\label{def:energy}
    Let $\epsilon,\mu\in (0,1]$ and let $J^s$ be the Bessel potential of order $-s$. We define the energy functional associated with \eqref{eq:whitham_boussinesq_d2} as
    \begin{align*}
        E_s(\eta,\mathbf{v}) = \int_{\mathbb{R}^2} \Big\{ \Big( J^s \eta \Big)^2 + (1+\epsilon\eta)\Big|J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathbf{v} \Big|^2 \Big\} \:\mathrm{d} x.
\end{align*}

\label{thm:refined_strichartz}
    Let $d\in \mathbb{N}\backslash\{0\}$ and $T>0$. Assume that $u : \mathbb{R}^d \times \mathbb{R} \rightarrow \mathbb{R}$ solves
    \eqref{eq:whitham_F_1}
    for a given symbol $M(\xi) \in \mathbb{R}$,  and that for some fixed pair $(q,r) \in [2,\infty] \times [2,\infty)$ the associated unitary group $S(t) = e^{itM(D)}$ satisfies 
 \eqref{GenericLocalised}
for all $\lambda >0$ dyadic, for given $A(\lambda) \in (0,\infty)$. Then
\begin{align}\label{GenericRefined}
  \lVertu\rVert_{L_T^2 L_x^\infty}
  &\lesssim
 \omega^{d(\frac{1}{2}-\frac{1}{\Tilde{r}})} T^{\frac{1}{2}} \lVertJ^{\Tilde{\theta}} P_{\le \omega} u\rVert_{L_T^\infty L_x^2}
 \\ \notag
 &+ \omega^{-\gamma} T^{\frac{1}{2}} \lVertJ^{\theta+\gamma}  \rho(\vert D \vert)^{-\frac{1}{q}} A(\vert D \vert)^{\frac{1}{2}-\frac{1}{r}} u\rVert_{L_T^\infty L_x^2}
  \\ \notag
  &+ \lVertJ^\theta \rho(\vert D \vert)^{1-\frac{1}{q}} A(\vert D \vert)^{\frac{1}{2}-\frac{1}{r}} F\rVert_{L_T^2 L_x^2}
\end{align}
for any $\Tilde{r}\in [2,\infty)$, $\Tilde{\theta} > d/\Tilde{r}$, $\theta > d/r$, and arbitrarily small $\gamma > 0$. Here we are free to choose $\omega > 0$ and $\rho(\lambda) \in (0,T]$.

For a number $\omega > 0$ to be chosen, we split into low and high frequencies:
\begin{align*}                    
    u = P_{\le \omega} u + \sum_{\lambda > \omega} P_\lambda u =: u_1 + u_2 ,
\end{align*}
giving us
\begin{align}\label{eq:decomp_u_ests}
    \lVertu\rVert_{L_T^2 L_x^\infty} \leq \lVertu_1\rVert_{L_T^2 L_x^\infty} +\lVertu_2\rVert_{L_T^2 L_x^\infty}.
\end{align}
\subsubsection*{\underline{Control of $\lVertu_1\rVert_{L_T^2 L_x^\infty}$ in \eqref{eq:decomp_u_ests}}}
By a Sobolev embedding and Bernstein's lemma in $x$, and H\"{o}lder's inequality in time, the low-frequency part is estimated by
\begin{equation}\label{GenericRefinedLow}
  \lVertu_1\rVert_{L_T^2 L_x^\infty} \lesssim  \lVert J^{\Tilde{\theta}} P_{\le \omega} u\rVert_{L_T^2 L_x^{\Tilde{r}}} \lesssim \omega^{d(\frac{1}{2}-\frac{1}{\Tilde{r}})} T^{\frac{1}{2}} \lVertJ^{\Tilde{\theta}} P_{\le \omega} u\rVert_{L_T^\infty L_x^2}
\end{equation}
for any $\Tilde{r}\in [2,\infty)$ and $\Tilde{\theta} > d/\Tilde{r}$.
\subsubsection*{\underline{Control of $\lVertu_2\rVert_{L_T^2 L_x^\infty}$ in \eqref{eq:decomp_u_ests}}}
By a Sobolev embedding, the Littlewood-Paley square function theorem, and Minkowski's integral inequality, we obtain
\[
  \lVertu_2\rVert_{L_T^2 L_x^\infty} \lesssim  \lVertJ^\theta u_2\rVert_{L_T^2 L_x^r} 
  \lesssim  \lVert\sqrt{ \sum_{\lambda > \omega} \left\vert  P_\lambda J^\theta u  \right\vert^2 } \rVert_{L_T^2 L_x^r}
  \lesssim \sqrt{ \sum_{\lambda > \omega} \lVert P_\lambda J^\theta u \rVert_{L_T^2 L_x^r}^2 }  
\]
for any $\theta > d/r$. Fix $\lambda > \omega$ and write $[0,T] = \bigcup_{j \in J} I_j$ where $I_j = [a_j,b_j]$ are almost disjoint, $\vert I_j \vert = \rho$ and $\# J = T/\rho$, where $\rho=\rho(\lambda) \in (0,T]$ remains to be chosen. Then, applying H\"older's inequality in time, we estimate
\[
  \lVert P_\lambda J^\theta u \rVert_{L_T^2 L_x^r}
  = \lVert \lVert P_\lambda J^\theta u \rVert_{L_{I_j}^2 L_x^r } \rVert_{\ell^2_{j\in J}}
  \le  \rho^{\frac{1}{2}-\frac{1}{q}}  \lVert\lVert P_\lambda J^\theta u \rVert_{L_{I_j}^q L_x^r} \rVert_{\ell^2_{j\in J}}.
\]
On $I_j$ we write
\[
  u(t) = S(t-a_j) u(a_j) + i \int_{a_j}^t S(t-s) F(s) \, ds
\]
and apply \eqref{GenericLocalised} to obtain
\begin{align*}
  \lVert P_\lambda J^\theta u \rVert_{L_{I_j}^q L_x^r}
  &\lesssim
  A(\lambda)^{\frac{1}{2}-\frac{1}{r}} \left( \lVertP_\lambda J^\theta u(a_j)\rVert_{L_x^2} + \int_{a_j}^t \lVertP_\lambda J^\theta F(s)\rVert_{L_x^2} \, ds \right)
  \\
  &\lesssim
  A(\lambda)^{\frac{1}{2}-\frac{1}{r}} \left( \lVertP_\lambda J^\theta u\rVert_{L_{I_j}^\infty L_x^2} + \rho^{\frac{1}{2}} \lVertP_\lambda J^\theta F\rVert_{L_{I_j}^2 L_x^2} \right).
\end{align*}
Taking the $\ell^2_{j\in J}$ norm, we conclude that
\begin{align*}
  \lVert P_\lambda J^\theta u \rVert_{L_T^2 L_x^r}
  &\lesssim  \rho^{\frac{1}{2}-\frac{1}{q}}   A(\lambda)^{\frac{1}{2}-\frac{1}{r}} \left( \sqrt{\# J} \lVertP_\lambda J^\theta u\rVert_{L_T^\infty L_x^2} + \rho^{\frac{1}{2}} \lVertP_\lambda J^\theta F\rVert_{L_T^2 L_x^2} \right)
  \\
  &\lesssim  \rho^{\frac{1}{2}-\frac{1}{q}}   A(\lambda)^{\frac{1}{2}-\frac{1}{r}} \left( T^{\frac{1}{2}} \rho^{-\frac{1}{2}} \lVertP_\lambda J^\theta u\rVert_{L_T^\infty L_x^2} + \rho^{\frac{1}{2}} \lVertP_\lambda J^\theta F\rVert_{L_T^2 L_x^2} \right).
\end{align*}
Finally, squaring and summing over dyadic $\lambda > \omega$ we obtain
\begin{align*}
   \lVertu_2\rVert_{L_T^2 L_x^\infty}  &\lesssim T^{\frac{1}{2}} \left( \sum_{\lambda > \omega} \lambda^{-2\gamma} \right)^{\frac{1}{2}}  \sup_{\lambda} \lVertP_\lambda J^{\theta+\gamma}  \rho(\vert D \vert)^{-\frac{1}{q}} A(\vert D \vert)^{\frac{1}{2}-\frac{1}{r}} u\rVert_{L_T^\infty L_x^2}
  \\
  &+ \lVertP_\lambda J^\theta \rho(\vert D \vert)^{1-\frac{1}{q}} A(\vert D \vert)^{\frac{1}{2}-\frac{1}{r}} F\rVert_{L_T^2 L_x^2}
\end{align*}
for any $\gamma > 0$. Thus
\begin{align}\label{GenericRefinedhigh}
   \lVertu_2\rVert_{L_T^2 L_x^\infty} &\lesssim \omega^{-\gamma} T^{\frac{1}{2}} \lVertJ^{\theta+\gamma} \rho(\vert D \vert)^{-\frac{1}{q}} A(D)^{\frac{1}{2}-\frac{1}{r}} u\rVert_{L_T^\infty L_x^2}
  \\ \notag
  &+ \lVertP_\lambda J^\theta \rho(\vert D \vert)^{1-\frac{1}{q}} A(\vert D \vert)^{\frac{1}{2}-\frac{1}{r}} F\rVert_{L_T^2 L_x^2}
\end{align}
for $\theta > \frac{d}{r}$ and arbitrarily small $\gamma > 0$.\\
\indent
Combining \eqref{GenericRefinedLow} and \eqref{GenericRefinedhigh} with \eqref{eq:decomp_u_ests} concludes the proof.

\label{disp:lemma} 
Let $d\in\{1,2\}$ and $\mu \in (0,1]$.
Then the dispersive decay bound
\begin{equation}\label{dispersive:1d}
   \lVertS_{\mu,d}(t) P_\lambda f\rVert_{L^\infty_x(\mathbb{R}^d)} \lesssim \mu^{-\frac{1}{2}} \vert t \vert^{-\frac{d}{2}} \lambda^{\frac{d}{2}-1} \langle{\sqrt{\mu} \lambda}\rangle^{\frac{d}{4}+1} \lVertf\rVert_{L^1_x(\mathbb{R}^d)}
\end{equation}
holds for $\lambda > 0$ and $t\in \mathbb{R}\backslash\{0\}$. Here, $S_{\mu,d}(t)$ is defined in \eqref{eq:unitary_group}.

\label{strichartz:lemma} Let $d \in \{1,2\}$ and $\mu \in (0,1]$. Assume that $2 < q \le \infty$ and $2 \le r \le \infty$ satisfy
\begin{equation}\label{eq:hyp_qr}
  \frac{2}{q} = d  \left( \frac{1}{2} - \frac{1}{r} \right).
\end{equation}
Then 
\begin{equation}\label{strichartz:1d}
   \lVertS_{\mu,d}(t) P_\lambda f\rVert_{L^q(\mathbb{R} ;L^r(\mathbb{R}^d))} \lesssim \left( \mu^{-\frac{1}{2}} \lambda^{\frac{d}{2}-1} \langle{\sqrt{\mu} \lambda}\rangle^{\frac{d}{4}+1} \right)^{\frac{1}{2}-\frac{1}{r}} \lVertP_\lambda f\rVert_{L^2(\mathbb{R}^d)}
\end{equation}
holds for all $\lambda > 0$, where $S_{\mu,d}(t)$ is defined in \eqref{eq:unitary_group}.

\label{cor:refined_strichartz_d_1}

    Let $d\in\{1,2\}$, $\mu \in(0,1]$,  and $T>0$, and let $u :\mathbb{R}^d  \times [0,T] \rightarrow \mathbb{R}$ solve 
    \begin{align}\label{eq:equation_refined_strichartz}
        \begin{dcases}
            i\partial_t u -\frac{1}{\sqrt{\mu}}m_d(\sqrt{\mu}D) u = F, \\
            u(x,0) = f(x),
        \end{dcases}
    \end{align}
    where the symbol $m_d(D)$ is defined in \eqref{eq:m_1}--\eqref{eq:m_2}.
    Then for $d=1$, we have
    \begin{align}\label{Refined:1d}
         \lVertu\rVert_{L_T^2 L_x^\infty}
         &\lesssim
         \mu^{-\frac{1}{5}+\frac{2\theta}{5}} T^{\frac{3}{10}+\frac{2\theta}{5}} \Big(\lVertJ^\theta \vert D \vert^{-\frac{1}{2}+\frac{3\theta}{2}} u\rVert_{L_T^\infty L_x^2}
         + \lVertJ_\mu^{\frac{5}{8}}  u\rVert_{L_T^\infty L_x^2}\Big)
          \\ \notag
          &+ \mu^{-\frac{2}{5}+\frac{\theta}{5}} T^{\frac{3}{5}+\frac{\theta}{5}} \lVert \vert D \vert^{-1} J_\mu^{\frac{5}{8}} F\rVert_{L_T^2 L_x^2}
    \end{align}
    and for $d=2$, it holds
    \begin{align}\label{Refined:2d}
         \lVertu\rVert_{L_T^2 L_x^\infty}
        & \lesssim
         \mu^{-\frac{1}{6} + \frac{5\theta}{36}} T^{\frac{1}{6} + \frac{5\theta}{18}} \Big(\lVertJ^{\theta} u\rVert_{L_T^\infty L_x^2}
         +  \lVert\vert D \vert^{\frac{1}{2}-\frac{\theta}{3}} J^{2\theta} J_\mu^{\frac{3}{4}}  u\rVert_{L_T^\infty L_x^2}\Big)
          \\ \notag
          &+ \mu^{-\frac{1}{3}+\frac{\theta}{9}} T^{\frac{1}{3}+\frac{2\theta}{9}} \lVert\vert D \vert^{-\frac{1}{2}-\frac{\theta}{3}} J^\theta J_\mu^{\frac{3}{4}} F\rVert_{L_T^2 L_x^2}
\end{align}
for $\theta > 0$ arbitrarily small.

We split the proof into two parts: one for $d=1$ and another for $d=2$.
    \subsubsection*{\underline{Proof of \eqref{Refined:1d}}}
    We start by fixing $q=4^+$ and $r=\infty^-$. More precisely, for $\theta > 0$ arbitrarily small we take $\frac{1}{q} = \frac{1}{4}-\frac{\theta}{4}$ and $\theta=\frac{2}{r}$.
    Then from Lemma \ref{strichartz:lemma} with
\[
  A(\lambda) = A_{\mu,1}(\lambda)
  =
  \mu^{-\frac{1}{2}} \lambda^{-\frac{1}{2}} \langle{\sqrt{\mu} \lambda}\rangle^{\frac{5}{4}},
\]
the bound \eqref{GenericRefined} now becomes
\begin{align*}
 \lVertu\rVert_{L_T^2 L_x^\infty}
 &\lesssim
 \omega^{\frac{1}{2}-\frac{\theta}{2}} T^{\frac{1}{2}} \lVertJ^\theta P_{\le \omega} u\rVert_{L_T^\infty L_x^2}
 \\
 &+ \omega^{-\theta} \mu^{-\frac{1}{4}+\frac{\theta}{4}} T^{\frac{1}{2}} \lVert\rho(\vert D \vert)^{-\frac{1}{4}+\frac{\theta}{4}} \vert D \vert^{-\frac{1}{4}+\frac{\theta}{4}} J^{2\theta} J_\mu^{\frac{5}{8}}  u\rVert_{L_T^\infty L_x^2}
  \\
  &+ \mu^{-\frac{1}{4}+\frac{\theta}{4}} \lVert\rho(\vert D \vert)^{\frac{3}{4}+\frac{\theta}{4}} \vert D \vert^{-\frac{1}{4}+\frac{\theta}{4}} J^\theta J_\mu^{\frac{5}{8}} F\rVert_{L_T^2 L_x^2}.
\end{align*}
We take $\rho(\lambda) = T^{\frac{4}{5}} \mu^{-\frac{1}{5}} \lambda^{-1}$. To get $\rho \le T$, we need $\lambda \ge \mu^{-\frac{1}{5}} T^{-\frac{1}{5}}$, so we choose
\[
  \omega = (\mu T)^{-\frac{1}{5}}.
\]
This yields
\begin{align*}
 \lVertu\rVert_{L_T^2 L_x^\infty}
 &\lesssim
 \mu^{-\frac{1}{10}+\frac{\theta}{10}} T^{\frac{2}{5}+\frac{\theta}{10}} \lVertJ^\theta P_{\le \omega} u\rVert_{L_T^\infty L_x^2}
 \\
 &+ \mu^{-\frac{1}{5}+\frac{2\theta}{5}} T^{\frac{3}{10}+\frac{2\theta}{5}} \lVertJ^{2\theta} J_\mu^{\frac{5}{8}}  u\rVert_{L_T^\infty L_x^2}
  \\
  &+ \mu^{-\frac{2}{5}+\frac{\theta}{5}} T^{\frac{3}{5}+\frac{\theta}{5}} \lVertJ^{\theta} \vert D \vert^{-1} J_\mu^{\frac{5}{8}} F\rVert_{L_T^2 L_x^2}.
\end{align*}
To match the powers of $\mu$ and $T$ in the first two terms on the right-hand side, we estimate
\[
   \lVertJ^\theta P_{\le \omega} u\rVert_{L_T^\infty L_x^2} = \lVertJ^\theta \vert D \vert^{\frac{1}{2}-\frac{3\theta}{2}} \vert D \vert^{-\frac{1}{2}+\frac{3\theta}{2}} P_{\le \omega} u\rVert_{L_T^\infty L_x^2} \lesssim \omega^{\frac{1}{2}-\frac{3\theta}{2}} \lVertJ^\theta \vert D \vert^{-\frac{1}{2}+\frac{3\theta}{2}} u\rVert_{L_T^\infty L_x^2} 
\]
so that finally
\begin{align*}                   
 \lVertu\rVert_{L_T^2 L_x^\infty}
 &\lesssim
 \mu^{-\frac{1}{5}+\frac{2\theta}{5}} T^{\frac{3}{10}+\frac{2\theta}{5}} \lVertJ^\theta \vert D \vert^{-\frac{1}{2}+\frac{3\theta}{2}} u\rVert_{L_T^\infty L_x^2}
 \\
 &+ \mu^{-\frac{1}{5}+\frac{2\theta}{5}} T^{\frac{3}{10}+\frac{2\theta}{5}} \lVertJ^{2\theta} J_\mu^{\frac{5}{8}}  u\rVert_{L_T^\infty L_x^2}
  \\
  &+ \mu^{-\frac{2}{5}+\frac{\theta}{5}} T^{\frac{3}{5}+\frac{\theta}{5}} \lVert J^{\theta}\vert D \vert^{-1} J_\mu^{\frac{5}{8}} F\rVert_{L_T^2 L_x^2}
\end{align*}
for $\theta > 0$ sufficiently small.
\subsubsection*{\underline{Proof of \eqref{Refined:2d}}}
We choose $q= 2^+$ and $r= \infty^-$. So, for $\theta > 0$ arbitrarily small, we take $\frac{1}{q} = \frac{1}{2}-\frac{\theta}{3}$ and $\theta=\frac{3}{r}$. We also let $\frac{1}{\Tilde{r}}=\frac{5\theta }{12}$ and $\Tilde{\theta} =\theta$. Then from Lemma \ref{strichartz:lemma}, we have
\[
  A(\lambda) = A_{\mu,2}(\lambda)
  =
  \mu^{-\frac{1}{2}} \langle{\sqrt{\mu} \lambda}\rangle^{\frac{3}{2}}.
\]
Consequently, the bound \eqref{GenericRefined} gives us
\begin{align*}
 \lVertu\rVert_{L_T^2 L_x^\infty}
 &\lesssim
 \omega^{1-\frac{5\theta}{6}} T^{\frac{1}{2}} \lVertJ^{\theta} P_{\le \omega} u\rVert_{L_T^\infty L_x^2}
 \\
 &+ \omega^{-\frac{\theta}{6}} \mu^{-\frac{1}{4}+\frac{\theta}{6}} T^{\frac{1}{2}} \lVert\rho(\vert D \vert)^{-\frac{1}{2}+\frac{\theta}{3}} J^{2\theta} J_\mu^{\frac{3}{4}}  u\rVert_{L_T^\infty L_x^2}
  \\
 & + \mu^{-\frac{1}{4}+\frac{\theta}{6}} \lVert\rho(\vert D \vert)^{\frac{1}{2}+\frac{\theta}{3}} J^\theta J_\mu^{\frac{3}{4}} F\rVert_{L_T^2 L_x^2}.
\end{align*}
We let $\rho(\lambda) = T^{\frac{2}{3}} \mu^{-\frac{1}{6}} \lambda^{-1}$. Then it requires $\lambda \ge \mu^{-\frac{1}{6}} T^{-\frac{1}{3}}$ to maintain $\rho \le T$, so we take
\[
  \omega = \mu^{-\frac{1}{6}} T^{-\frac{1}{3}}.
\]
This gives us
\begin{align*}
 \lVertu\rVert_{L_T^2 L_x^\infty}
& \lesssim
 \mu^{-\frac{1}{6} + \frac{5\theta}{36}} T^{\frac{1}{6} + \frac{5\theta}{18}} \lVertJ^{\theta} u\rVert_{L_T^\infty L_x^2}
 \\
 &+ \mu^{-\frac{1}{6}+\frac{5\theta}{36}} T^{\frac{1}{6}+\frac{5\theta}{18}} \lVert\vert D \vert^{\frac{1}{2}-\frac{\theta}{3}} J^{2\theta} J_\mu^{\frac{3}{4}}  u\rVert_{L_T^\infty L_x^2}
  \\
  &+ \mu^{-\frac{1}{3}+\frac{\theta}{9}} T^{\frac{1}{3}+\frac{2\theta}{9}} \lVert\vert D \vert^{-\frac{1}{2}-\frac{\theta}{3}} J^\theta J_\mu^{\frac{3}{4}} F\rVert_{L_T^2 L_x^2}
\end{align*}
for $\theta > 0$ small enough.

Let $s \geq 0$, $p\in (1,\infty)$, $f\in H^s(\mathbb{R}^d)$, and $g\in H^{s-1}(\mathbb{R}^d)$.  Then
    \begin{align}\label{eq:kato_ponce}
        \lVert[J^s,f] g\rVert_{L^p_x} \lesssim \lVert\nabla f\rVert_{L^\infty_x} \lVertJ^{s-1} g\rVert_{L^p_x} + \lVertJ^s f\rVert_{L^p_x} \lVert g\rVert_{L^\infty_x}.
    \end{align}
    Moreover,  let $p_1,p_4 \in (1,\infty]$ and $p_2,p_3\in (1,\infty)$ be such that $\frac{1}{p}= \frac{1}{p_1} + \frac{1}{p_2} = \frac{1}{p_3} + \frac{1}{p_4}$. Then
    \begin{align}\label{eq:kato_ponce_ineq}
        \lVertJ^s(f g)\rVert_{L^p_x} \lesssim \lVertf\rVert_{L^{p_1}_x} \lVertJ^{s} g\rVert_{L^{p_2}_x}  + \lVertJ^s f\rVert_{L^{p_3}_x} \lVert g\rVert_{L^{p_4}_x}
    \end{align}
    for $f,g\in H^s(\mathbb{R}^d)$.

\label{prop:energy1_whitham}
    Let $s>\frac{3}{2}$ and $\epsilon,\mu \in (0,1]$. Let $r \ge s+1$ and $T > 0$. Then for any solution $\eta \in C([0,T];H^r(\mathbb{R}))$ to \eqref{eq:Whitham} on the time interval $[0,T]$ we have
     \begin{align}\label{eq:energy_est_whitham}
         \frac{\:\mathrm{d}}{\:\mathrm{d} t} (\lVert\eta(t)\rVert_{H^s_x}^2) \le c  \epsilon \lVert\partial_x \eta(t)\rVert_{L^\infty_x} \lVert\eta(t)\rVert_{H^s_x}^2
     \end{align}
     for $t\in(0,T)$.

From \eqref{eq:Whitham}, we have 
    \begin{align*}
         \frac{1}{2}\frac{\:\mathrm{d}}{\:\mathrm{d} t} (\lVert\eta\rVert_{H^s_x}^2) &= \big({J^s \eta},{J^s \partial_t \eta}\big)_{L^2_x} \\
         &= - \big({J^s \eta},{J^s \sqrt{\mathcal{T}_\mu}(D) \partial_x \eta}\big)_{L^2_x} - \epsilon \big({J^s \eta},{J^s (\eta\partial_x \eta)}\big)_{L^2_x}.
    \end{align*}
    Here, the first term is skew-symmetric, and the second term can be estimated by H\"{o}lder's inequality, the Kato-Ponce commutator estimate \eqref{eq:kato_ponce}, and integration by parts. So, we obtain
    \begin{align*}
       \frac{\:\mathrm{d}}{\:\mathrm{d} t} (\lVert\eta\rVert_{H^s_x}^2)                                                                               
       &\leq 2\epsilon |\big({J^s \eta},{[J^s ,\eta]\partial_x \eta}\big)_{L^2_x}| + 2\epsilon |\big({J^s \eta},{\eta J^s \partial_x \eta}\big)_{L^2_x}|\\
        &\le c \epsilon \lVert\partial_x \eta\rVert_{L^\infty_x} \lVert\eta\rVert^2_{H^s_x}
    \end{align*}
    as desired.

\label{cor:energy1_whitham}
    Let $s>\frac{3}{2}$, $T > 0$ and $\epsilon,\mu \in (0,1]$. Then for any solution $\eta \in C([0,T];H^s(\mathbb{R}))$ to \eqref{eq:Whitham} on $[0,T]$ with $\eta(0)=\eta_0$ we have
     \begin{equation}\label{eq:gronwall_whitham}
         \lVert\eta(t)\rVert_{H^s_x}^2
         \le
         \mathrm{e}^{c \epsilon \int_0^t \lVert\partial_x \eta(\tau)\rVert_{L^\infty_x} \!\:\mathrm{d} \tau} \lVert\eta_0\rVert_{H^s_x}^2
     \end{equation}
     for $t\in [0,T]$.

\label{prop:boundedness_whitham}
    Let $\epsilon,\mu\in (0,1]$, $r>\frac{13}{8}$, and $T>0$. Let $\eta \in C([0,T];H^{r}(\mathbb{R}))$ be a solution to \eqref{eq:Whitham}. Then
    \begin{align}\label{eq:boundedness_whitham}
      \lVert\partial_x \eta\rVert_{L^2_TL^\infty_x} &\lesssim  \mu^{(-\frac{1}{5})^+ }   T^{\frac{3}{10}^+}  \lVert\eta\rVert_{L^\infty_TH^{r}_x} +  \epsilon  \mu^{(-\frac{2}{5})^+}  T^{\frac{11}{10}^+} \lVert\eta\rVert_{L^\infty_T H^{r}_x}^2.
      \end{align}

We observe that the Whitham equation \eqref{eq:Whitham} has the same form as \eqref{eq:equation_refined_strichartz} for $u=\eta$ and $F = -i\frac{\epsilon}{2}\partial_x( \eta^2)$. With these choices, we have from \eqref{Refined:1d} and H\"{o}lder's inequality in time that
    \begin{align*}
        \lVert\partial_x \eta\rVert_{L_T^2 L_x^\infty}
         &\lesssim
         \mu^{-\frac{1}{5}+\frac{2\theta}{5}} T^{\frac{3}{10}+\frac{2\theta}{5}} \Big(\lVertJ^\theta \vert D \vert^{\frac{1}{2}+\frac{3\theta}{2}} \eta\rVert_{L_T^\infty L_x^2} +  \lVertJ_\mu^{\frac{5}{8}}  |D| \eta\rVert_{L_T^\infty L_x^2}\Big)
          \\ \notag
          &+ \epsilon \mu^{-\frac{2}{5}+\frac{\theta}{5}} T^{\frac{11}{10}+\frac{\theta}{5}} \lVert J_\mu^{\frac{5}{8}} |D|  (\eta^2)\rVert_{L_T^\infty L_x^2}
    \end{align*}
    for sufficiently small $\theta >0$.  Then by the Kato-Ponce inequality \eqref{eq:kato_ponce_ineq} and a Sobolev embedding we obtain \eqref{eq:boundedness_whitham} 
    for $r>\frac{13}{8}$.

Arguing as in \cite{Saut1979} and \cite{Bona1975}, one get the following local well-posedness result for the Whitham equation \eqref{eq:Whitham}:
    \begin{prop}\label{prop:existence_whitham}
        Let $s>\frac{3}{2}$, $\epsilon,\mu \in (0,1]$, and $\eta_0 \in H^{s}(\mathbb{R})$. Then there exists a positive time $T = T(\lVert\eta_0\rVert_{H^s_x})$, decreasing with respect to its arguement, such that there is a unique $\eta \in C([0, T ] ; H^s(\mathbb{R}))$ solving \eqref{eq:Whitham} with initial condition $\eta(0) = \eta_0$. Moreover,
        \begin{align*}
            \sup_{t\in [0,T]} \lVert\eta(t)\rVert_{H^s_x} \lesssim\lVert\eta_0\rVert_{H^s_x},
        \end{align*}
        and the flow map is continuously dependent on the initial datum.  Furthermore, higher regularity persists. That is, if $\eta_0 \in H^r(\mathbb{R})$ for some $r > s$, then $\eta$ belongs to the space $C([0, T ] ; H^r(\mathbb{R}))$ (with the same $T$).
    \end{prop}
    \begin{remark}
        The time of existence of order $1/\epsilon$ was obtained in \cite{Klein2018}.
    \end{remark}






We only need to prove that the time of existence is of order $\epsilon^{-1} (\mu/\epsilon)^{\frac{1}{4}^-}$. 

 Indeed, the uniqueness, continuous dependence on the data, and persistence of higher regularity are local-in-time properties and follow directly from Proposition \ref{prop:existence_whitham}; see Remarks \ref{rem:w_rem1}--\ref{rem:w_rem3} below.











We notice that a consequence of Proposition \ref{prop:existence_whitham}, the initial datum $\eta_0 \in H^s(\mathbb{R})$, for $s> \frac{3}{2}$, gives the rise to a solution to \eqref{eq:Whitham}, $\eta \in C([0,T^\ast);H^s(\mathbb{R}))$, where $T^\ast \geq T(\lVert\eta_0\rVert_{H^s_x})$ is the maximal time of existence. Here, $T$ is a decreasing function of its argument. Then it also follows that the solution satisfies the blow-up alternative:
    \begin{align}\label{eq:BA}
        \text{If } \ \ T^\ast <\infty, \text{ then } \limsup_{t\nearrow T^\ast} \lVert\eta(t)\rVert_{H^s_x} = \infty
    \end{align}
    (see, e.g., \cite[Section 5.2]{Iorio2001}).








With Proposition \ref{prop:existence_whitham}, we may now obtain the a priori estimates and prove that the solution exists on a larger timescale. This is summarized in the lemma below.

\begin{lem}\label{lem:bootstrap_whitham}
Let $s>\frac{13}{9}$ and $\epsilon,\mu \in (0,1]$. Then there exists a positive time 
\begin{align}\label{eq:w_time_t0}
     T_0 = c^{-1} \epsilon^{-1} \left( \frac{\mu}{\epsilon} \right)^{\frac{1}{4}^-} \lVert\eta_0\rVert_{H^s_x}^{(-\frac{5}{4})^+}
\end{align}
such that $T^\ast > T_0$ and 
\begin{align*}
    \sup_{t\in [0,T_0]}\lVert\eta(t)\rVert_{H^s_x}  \leq 4 \lVert\eta_0\rVert_{H^s_x} .
\end{align*}
\end{lem}






\begin{proof}                                             
    We will argue by contradiction by defining 
    \begin{align}\label{eq:T_tilde_nu_whitham}
        \Tilde{T} := \sup \{ T \in (0,T^\ast) : \sup_{t\in [0,T]} \lVert\eta(t)\rVert_{H^{s}_x} \leq 4 \lVert\eta_0\rVert_{H^{s}_x} \}
    \end{align}
    and assuming that $\Tilde{T} \leq T_0$. Obtaining an estimate inside the ball in \eqref{eq:T_tilde_nu_whitham} for the time $T_0$ defined in \eqref{eq:w_time_t0} will lead to a contradiction.

    Fix $T_1 \in (0,\Tilde{T})$, then we utilize \eqref{eq:gronwall_whitham},  \eqref{eq:boundedness_whitham}, and the assumption $T_1 <\Tilde{T} \leq T_0$ to obtain
    \begin{align*}                                          
        \lVert\eta(t)\rVert_{H^{s}_x}^2 &\leq  \mathrm{e}^{c\epsilon T_1^\frac{1}{2}  \lVert\partial_x \eta\rVert_{L^2_{T_1}L^\infty_x} }   \lVert\eta_0\rVert_{H^{s}_x}^2\\
        &\leq \mathrm{e}^{c \mu^{(-\frac{1}{5})^+} \epsilon T_0^{\frac{4}{5}^+} \lVert\eta_0\rVert_{H^{s}_x} + c \mu^{(-\frac{2}{5})^+} \epsilon^2 T_0^{\frac{8}{5}^+} \lVert\eta_0\rVert_{H^{s}_x}^2 }   \lVert\eta_0\rVert_{H^{s}_x}^2\\
        &=: \mathrm{e}^{c(\delta + \delta^2)}   \lVert\eta_0\rVert_{H^{s}_x}^2
    \end{align*}
    for all $t\in [0,T_1]$ and $s>\frac{13}{8}$. Choosing $T_0>0$ small enough such that
    \begin{align*}
        2c \delta < \log 2,
    \end{align*}
    yielding $c(\delta + \delta^2) < 2c \delta $ and \eqref{eq:w_time_t0},  implies
    \begin{align*}
        \lVert\eta(t)\rVert_{H^{s}_x} & \leq 2\lVert\eta_0\rVert_{H^{s}_x}
    \end{align*}
    for all $t\in [0,T_1]$. As a consequence of \eqref{eq:BA}, we have that $T_1< T^\ast$. Then by the continuity of the solution $\eta(t)$ for $t\in [0,T^\ast)$ from the definition of $T^\ast$, there exists a time $\tau \in [\Tilde{T},T^\ast)$ such that 
    \begin{align*}
        \lVert\eta(\tau)\rVert_{H^s_x} \leq 3\lVert\eta_0\rVert_{H^s_x}.
    \end{align*}
    But this leads to a contradiction of the definition of $\Tilde{T}$ in \eqref{eq:T_tilde_nu_whitham}. We may therefore conclude that indeed $T_0 < \Tilde{T}$, where $T_0$ is defined in \eqref{eq:w_time_t0}.
    \renewcommand$\overset{\text{Lemma \ref{lem:bootstrap_wb}}}{\ensuremath{\Box}}${$\overset{\text{Lemma \ref{lem:bootstrap_whitham}}}{\ensuremath{\Box}}$}
\end{proof}

\addtocontents{toc}{\gobblefive}\subsubsection*{Conclusion.}  
We conclude the proof of Theorem \ref{thm:wellposedness_Whitham} with some remarks on uniqueness, continuous dependence on data, and persistence of higher regularity. All these properties are known for some positive time by the local existence and uniqueness result, Proposition \ref{prop:existence_whitham}, and they therefore extend to the larger time interval $[0,T_0]$ by standard arguments which we briefly recall in the following remarks. In these remarks we assume that $\eta,\tilde\eta \in C([0,T];H^s(\mathbb{R}))$ are two solutions of the Whitham equation with initial data $\eta_0,\tilde\eta_0\in H^s(\mathbb{R})$, respectively. Here $T > 0$ is completely arbitrary.

\begin{remark}\label{rem:w_rem1}
For uniqueness, assume that $\eta_0=\tilde\eta_0$. If uniqueness fails, then for some $S \in (0,T)$ we have $\eta=\tilde\eta$ in $[0,S]$ while this fails on $[S,S+\delta]$ for all $\delta > 0$. But applying Proposition \ref{prop:existence_whitham} with initial time $t=S$, this contradicts the uniqueness part of the proposition.
\end{remark}

\begin{remark}\label{rem:w_rem2}
For continuous dependence on the data, we must show that given any $\varepsilon > 0$ there exists $\delta > 0$ such that if $\lVert\eta_0-\tilde\eta_0\rVert_{H^s_x} < \delta$, then $\sup_{t \in [0,T]} \lVert\eta(t)-\tilde\eta(t)\rVert_{H^s_x} < \varepsilon$. Choose $R > 0$ so large that $\lVert\eta(t)\rVert_{H^s_x}, \lVert\tilde\eta(t)\rVert_{H^s_x} \le R$ for all $t \in [0,T]$. Now let $S=S(R) > 0$ be the time in Proposition \ref{prop:existence_whitham}. We may assume that $S=T/N$ for a large integer $N$. Then applying the continuous dependence on the data in Proposition \ref{prop:existence_whitham} first at the initial time $t_1:=T-S$, we find first $\delta_1 > 0$ such that if $\lVert\eta(t_1)-\tilde\eta(t_1)\rVert_{H^s_x} < \delta_1$, then $\sup_{t \in [t_1,T]} \lVert\eta(t)-\tilde\eta(t)\rVert_{H^s_x} < \varepsilon$. Next, repeating the argument at the initial time $t_2:=t_1-S=T-2S$ we obtain $\delta_2 \in (0,\delta_1]$ such that if $\lVert\eta(t_2)-\tilde\eta(t_2)\rVert_{H^s_x} < \delta_2$, then $\sup_{t \in [t_2,t_1]} \lVert\eta(t)-\tilde\eta(t)\rVert_{H^s_x} < \delta_1$, etc.
\end{remark}

\begin{remark}\label{rem:w_rem3}
For persistence of higher regularity, assume that $\eta_0$ belongs to $H^r(\mathbb{R})$ for some $r > s$. Choose $R > 0$ so large that $\lVert\eta(t)\rVert_{H^s_x} \le R$ for all $t \in [0,T]$, let $S=S(R) > 0$ be the time in Proposition \ref{prop:existence_whitham}, and assume that $S=T/N$ for an integer $N$. Applying the persistence property in Proposition \ref{prop:existence_whitham} on the successive time intervals $[0,S]$, $[S,2S]$ etc., we conclude that $\eta$ belongs to  $C([0,T];H^r(\mathbb{R}))$.
\end{remark}

\label{prop:existence_whitham}
        Let $s>\frac{3}{2}$, $\epsilon,\mu \in (0,1]$, and $\eta_0 \in H^{s}(\mathbb{R})$. Then there exists a positive time $T = T(\lVert\eta_0\rVert_{H^s_x})$, decreasing with respect to its arguement, such that there is a unique $\eta \in C([0, T ] ; H^s(\mathbb{R}))$ solving \eqref{eq:Whitham} with initial condition $\eta(0) = \eta_0$. Moreover,
        \begin{align*}
            \sup_{t\in [0,T]} \lVert\eta(t)\rVert_{H^s_x} \lesssim\lVert\eta_0\rVert_{H^s_x},
        \end{align*}
        and the flow map is continuously dependent on the initial datum.  Furthermore, higher regularity persists. That is, if $\eta_0 \in H^r(\mathbb{R})$ for some $r > s$, then $\eta$ belongs to the space $C([0, T ] ; H^r(\mathbb{R}))$ (with the same $T$).

\label{lem:bootstrap_whitham}
Let $s>\frac{13}{9}$ and $\epsilon,\mu \in (0,1]$. Then there exists a positive time 
