\label{def:symb_class}
    We say that a symbol $\sigma(D)$ is an element of the symbol class $\mathtt{S}^s$ with $s\in \mathbb{R}$, if $\xi \in \mathbb{R}^d \mapsto \sigma (\xi) \in \mathbb{C}$ is smooth and satisfies 
    \begin{align*}                       
        \forall \alpha \in \mathbb{N}^d, \ \ \sup_{\xi \in \mathbb{R}^d} \ \langle{\xi}\rangle^{|\alpha|- s} \Big| \frac{\partial^\alpha}{\partial\xi^\alpha} \sigma(\xi)  \Big| < \infty. 
    \end{align*}
    We also introduce the following semi-norm
    \begin{align*}                                
        \mathcal{N}^s(\sigma) = \sup_{\alpha\in \mathbb{N}^d, \:  |\alpha| \leq 2+d+\lceil\frac{d}{2} \rceil}\: \sup_{\xi \in \mathbb{R}^d} \ \langle{\xi}\rangle^{|\alpha|-s} \Big| \frac{\partial^\alpha}{\partial \xi^\alpha }  \sigma(\xi) \Big|.
    \end{align*}

\label{lem:gen_kato_ponce}
    Let $s\geq 0$, $t_0>\frac{d}{2}$, and $\sigma \in \mathtt{S}^s$. If $f\in H^s(\mathbb{R}^d)\cap H^{t_0+1}(\mathbb{R}^d)$ and $g\in H^{s-1}(\mathbb{R}^d) \cap H^{t_0}(\mathbb{R}^d)$, then
    \begin{align}\label{eq:gen_kato_ponce_Linfty}
        \lVert[\sigma(D),f]g\rVert_{L^2_x} &\lesssim \mathcal{N}^s(\sigma) (\lVert\nabla f\rVert_{L^\infty_x}\lVertg\rVert_{H^{s-1}_x} + \lVert\nabla f\rVert_{H^{s-1}_x}\lVertg\rVert_{L^\infty_x}).



\end{align}

\label{lem:derivatives_Tilbert}
    Let $\mu \in (0,1]$. Then the symbol $\mathcal{T}_\mu(\xi)$ defined in \eqref{eq:def_T_mu_xi} satisfies
    \begin{align}                          
    \notag
        \mathcal{T}_\mu (\xi) \langle{\sqrt{\mu}\xi}\rangle &\sim 1,
        \\
        \Big|\frac{\partial^\alpha}{\partial \xi^\alpha}\sqrt{\mathcal{T}_\mu (\xi)} \Big| &\lesssim \mu^{\frac{|\alpha|}{2}} \langle{\sqrt{\mu}\xi}\rangle^{-\frac{1}{2} - |\alpha|}
        \label{eq:derivatives_Tilbert}
    \end{align}
    for any $\alpha\in \mathbb{N}^d$.

\label{cor:est_on_Tilbert_symbol}
Let $\mu \in (0,1]$. Then the symbol $\sqrt{\mathcal{T}_\mu(\xi)}$ defined in \eqref{eq:def_T_mu_xi} satisfies
    \begin{align}\label{eq:derivatives_Tilbert_inv}
        \Big|\frac{\partial^\alpha}{\partial \xi^\alpha}\frac{1}{\sqrt{\mathcal{T}_\mu (\xi)}} \Big| & \lesssim \mu^{\frac{|\alpha|}{2}} \langle{\sqrt{\mu}\xi}\rangle^{\frac{1}{2}- |\alpha|}
    \end{align}
    for any $\alpha\in \mathbb{N}^d$.

\label{lem:commutator_est_tilbert}
    Let  $\mu \in (0,1]$, $s\geq 0$, $t_0>\frac{d}{2}$, $f\in H^s(\mathbb{R}^d)\cap H^{t_0+1}(\mathbb{R}^d)$, and $g\in H^{s-1}(\mathbb{R}^d) \cap H^{t_0}(\mathbb{R}^d)$, then
    \begin{align} \label{eq:commutator_est_tilbert2}
        \lVert[J^s\sqrt{\mathcal{T}_\mu}(D),f] g\rVert_{L^2_x} &\lesssim \lVert\nabla f\rVert_{L^\infty_x}\lVertJ^{s-1} g\rVert_{L^2_x} + \lVertJ^s f\rVert_{L^2_x}\lVertg\rVert_{L^\infty_x}.
    \end{align}

We will use \eqref{eq:gen_kato_ponce_Linfty} to obtain the commutator estimate \eqref{eq:commutator_est_tilbert2}. In other words, we need to verify that  $J^s \sqrt{\mathcal{T}_\mu} \in \mathtt{S}^s$ and calculate $\mathcal{N}^s(J^s \sqrt{\mathcal{T}_\mu})$, which are defined in Definition \ref{def:symb_class}. From  the Leibniz rule and \eqref{eq:derivatives_Tilbert}, it follows that
    \begin{align*}
        \langle{\xi}\rangle^{|\alpha|-s} \Big| \frac{\partial^\alpha}{\partial\xi^\alpha} \Big( \sqrt{\mathcal{T}_\mu(\xi)} \langle{\xi}\rangle^{s}\Big) \Big|  \lesssim \langle{\xi}\rangle^{|\alpha|-s} \sum_{\gamma\in \mathbb{N}^d\: : \: \gamma\leq \alpha} \mu^{\frac{|\alpha|-|\gamma|}{2}} \langle{\sqrt{\mu}\xi}\rangle^{-\frac{1}{2} - (|\alpha|-|\gamma|)} \langle{\xi}\rangle^{s-|\gamma|} \lesssim  1,
    \end{align*}
    where the implicit constant is independent of $\mu \in (0,1]$. Consequently, $J^s\sqrt{\mathcal{T}_\mu} \in \mathtt{S}^s$ and $\mathcal{N}^s(J^s\sqrt{\mathcal{T}_\mu} ) \lesssim 1$ uniformly in $\mu$. Then, we have from \eqref{eq:gen_kato_ponce_Linfty} that 
    \begin{align*}
        \lVert[J^s \sqrt{\mathcal{T}_\mu}(D),f] g\rVert_{L^2_x}                                                                                                                  
        &\lesssim \lVert\nabla f\rVert_{L^\infty_x}\lVertg\rVert_{H^{s-1}_x} + \lVertf\rVert_{H^s_x}\lVertg\rVert_{L^\infty_x}
    \end{align*}
    as desired.

\label{lem:commutator_inv_tilbert}
    Let $\mu\in(0,1]$, $s\geq 0$, $t_0 >\frac{d}{2}$, $f\in H^s(\mathbb{R}^d)\cap H^{t_0+1}(\mathbb{R}^d)$, and $g\in H^{s-1}(\mathbb{R}^d) \cap H^{t_0}(\mathbb{R}^d)$. Then 
    \begin{align}\label{eq:commutator_est_tilbert_inv}
        \lVert[ J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) , f]g\rVert_{L^2_x} &\lesssim \lVert\nabla f\rVert_{L^\infty_x} \lVertJ^{s-1} J^\frac{1}{2}_\mu g\rVert_{L^2_x} + \lVertJ^s J^\frac{1}{2}_\mu f\rVert_{L^2_x}\lVertg\rVert_{L^\infty_x}
        .
    \end{align}

Let $\chi^{(j)} \in \mathcal{S}(\mathbb{R}^d)$  be Fourier multipliers for $j=1,2$, that is,
    \begin{align*}
        \mathcal{F}(\chi^{(j)}(D)f)(\xi) = \chi^{(j)}(|\xi|) \widehat{f}(\xi)
    \end{align*}
    for all $f\in \mathcal{S}(\mathbb{R}^d)$ such that
    \begin{align*}
        0\leq \chi^{(j)}(|\xi|) \leq 1, \ \ \ \chi^{(1)}(|\xi|) + \chi^{(2)}(|\xi|) = 1
    \end{align*}
    on $\mathbb{R}^d$ with the support 
    \begin{align*}
        \mathrm{supp} \: \chi^{(1)}(|\xi|) \subset [-2,2], \ \ \ \mathrm{supp} \: \chi^{(2)}(|\xi|) \subset \mathbb{R}\backslash[-1,1].
    \end{align*}
    We let
    \begin{align*}
        \chi^{(j)}_\mu(|\xi|) := \chi^{(j)}(\sqrt{\mu}|\xi|)
    \end{align*}
    be the scaled version.
  With these smooth cut-off functions, we can write
    \begin{align*}
        \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) &=(\chi^{(1)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}})(D) + (\chi^{(2)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}})(D) .
    \end{align*}
     It then follows that






     \begin{align}\label{eq:commutator_part_123}
         \lVert[ J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) , f]g \rVert_{L^2_x} 
         &\leq \lVert[J^s (\chi^{(1)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}})(D) , f]g\rVert_{L^2_x} 
         +\lVert[J^s (\chi^{(2)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}})(D) , f]g\rVert_{L^2_x} 
         \\ \notag
         &=: \mathscr{A}_1 + \mathscr{A}_2.
     \end{align}
     To obtain \eqref{eq:commutator_est_tilbert_inv}, we will estimate each of these terms separately, utilizing \eqref{eq:gen_kato_ponce_Linfty}.
     \addtocontents{toc}{\gobblefive}\subsubsection*{Control of $\mathscr{A}_1$ in \eqref{eq:commutator_part_123}}
     We start by estimating $\mathscr{A}_1$, i.e., verifying that $J^s(\chi^{(1)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}})\in \mathtt{S}^{s}$ and $\mathcal{N}^s(J^s(\chi^{(1)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}})) \lesssim 1$ uniformly in $\mu \in (0,1]$. We first make the observation that 
    \begin{align}\label{eq:chi_est}
        \mu^\frac{|\gamma|}{2}\langle{\xi}\rangle^{|\gamma|} \Big|\Big( \frac{\partial^\gamma}{\partial \xi^\gamma}\chi_\mu^{(1)}\Big)(\sqrt{\mu}|\xi|) \Big| \lesssim 1
    \end{align}
    for  $\gamma \in \mathbb{N}^d$. Additionally, on the support of $\chi^{(1)}_\mu$ and its derivatives, the estimate \eqref{eq:derivatives_Tilbert_inv} becomes
    \begin{align*}
        \Big| \frac{\partial^\gamma}{\partial\xi^\gamma}\frac{1}{\sqrt{\mathcal{T}_\mu(\xi)}}  \Big| & \lesssim \mu^{\frac{|\gamma|}{2}} \langle{\sqrt{\mu}\xi}\rangle^{\frac{1}{2} - |\gamma|} \lesssim \langle{\xi}\rangle^{-|\gamma|}.
    \end{align*}
    Then, the Leibniz rule gives us
    \begin{align*}
        \Big| \frac{\partial^\gamma}{\partial\xi^\gamma} \Big(\chi^{(1)}_\mu(|\xi|)\frac{1}{\sqrt{\mathcal{T}_\mu(\xi)}} \Big) \Big|                                                                                                                                                                                                                                                          
        &\lesssim \sum_{\kappa \in \mathbb{N}^d \: :  \: \kappa \leq \gamma} \mu^\frac{|\gamma|-|\kappa|}{2} \Big|\Big( \frac{\partial^{\gamma-\kappa}}{\partial \xi^{\gamma-\kappa}}\chi^{(1)}\Big)(\sqrt{\mu}|\xi|) \Big| \langle{\xi}\rangle^{-|\kappa|}.
    \end{align*}
    With the above estimate, the Leibniz rule, and \eqref{eq:chi_est}, we obtain
    \begin{align*}
        \langle{\xi}\rangle^{|\alpha|-s} \Big| \frac{\partial^\alpha}{\partial\xi^\alpha} \Big(\langle{\xi}\rangle^s \chi^{(1)}_\mu\frac{1}{\sqrt{\mathcal{T}_\mu(\xi)}}\Big)  \Big|

        &\lesssim \sum_{\gamma\leq \alpha}    \sum_{\kappa\leq \gamma} \mu^\frac{|\gamma|-|\kappa|}{2} \Big|\Big( \frac{\partial^{\gamma-\kappa}}{\partial \xi^{\gamma-\kappa}}\chi^{(1)}\Big)(\sqrt{\mu}|\xi|) \Big| \langle{\xi}\rangle^{|\gamma|-|\kappa|}  \lesssim 1.
    \end{align*}
    Then \eqref{eq:gen_kato_ponce_Linfty} yields 
    \begin{align}\label{eq:B1}
        \mathscr{A}_1 &\lesssim \lVert\nabla f\rVert_{L^\infty_x}\lVertJ^{s-1}  g\rVert_{L^2_x} + \lVertJ^s f\rVert_{L^2_x}\lVertg\rVert_{L^\infty_x}\\ \notag
        &\lesssim  \lVert\nabla f\rVert_{L^\infty_x} \lVertJ^{s-1} J^\frac{1}{2}_\mu g\rVert_{L^2_x} + \lVertJ^s J^\frac{1}{2}_\mu f\rVert_{L^2_x}\lVert g\rVert_{L^\infty_x}.
    \end{align} 
    \addtocontents{toc}{\gobblefive}\subsubsection*{Control of $\mathscr{A}_2$ in \eqref{eq:commutator_part_123}}
    The term $\mathscr{A}_2$ in \eqref{eq:commutator_part_123} will also be estimated with the help of  Lemma \ref{lem:gen_kato_ponce}. To verify that $J^s(\chi^{(2)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}}) \in \mathtt{S}^{s+\frac{1}{2}}$, it suffices to show that
    \begin{align*}
        \sup_{\xi\in\mathbb{R}^d}  \langle{\xi}\rangle^{|\alpha| - (s+\frac{1}{2})} \Big| \frac{\partial^\alpha}{\partial\xi^\alpha} \Big(\langle{\xi}\rangle^s \chi^{(2)}_\mu \frac{1}{\sqrt{\mathcal{T}_\mu(\xi)}}\Big) \Big|  \lesssim \mu^\frac{1}{4}.
    \end{align*}
    We first write
    \begin{align*}
        \frac{1}{\sqrt{\mathcal{T}_\mu(\xi)}}&= \mu^\frac{1}{4}|\xi|^\frac{1}{2}
        \frac{1}{(\tanh(\sqrt{\mu}|\xi|))^\frac{1}{2}}.
    \end{align*}
    Then, on the support of $\chi^{(2)}$ and its derivative, we have that $\frac{1}{(\tanh(\sqrt{\mu}|\xi|))^\frac{1}{2}}$ and its derivatives are uniformly bounded, and $|\xi| \geq \sqrt{\mu}|\xi|>1$. In other words, $J^s(\chi^{(2)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}}) \in \mathtt{S}^{s+\frac{1}{2}}$ and $\mathcal{N}^{s+\frac{1}{2}}(J^s(\chi^{(2)}_\mu \mathcal{T}_{\mu}^{-\frac{1}{2}}))\lesssim \mu^\frac{1}{4}$. Thus, we conclude by \eqref{eq:gen_kato_ponce_Linfty} that
    \begin{align}\label{eq:B3}
       \mathscr{A}_2 &\lesssim
        \mu^\frac{1}{4} \lVert\nabla f\rVert_{L^\infty_x}\lVertg\rVert_{H^{s-\frac{1}{2}}_x} + \mu^\frac{1}{4}\lVert\nabla f\rVert_{H^{s-\frac{1}{2}}_x}\lVert g\rVert_{L^\infty_x}
        \\ \notag
        &\lesssim \lVert\nabla f\rVert_{L^\infty_x} \lVertJ^{s-1} J^\frac{1}{2}_\mu g\rVert_{L^2_x} + \lVertJ^s J^\frac{1}{2}_\mu f\rVert_{L^2_x}\lVert g\rVert_{L^\infty_x}.
    \end{align}
    We complete the proof of \eqref{eq:commutator_est_tilbert_inv} by combining \eqref{eq:commutator_part_123} with \eqref{eq:B1} and \eqref{eq:B3}.

Let $f\in \mathcal{S}(\mathbb{R}^d)$, $\mu \in (0,1]$, and $s\in \mathbb{R}$. Then
    \begin{align}\label{eq:est_on_tilbert}
        \lVert\sqrt{\mathcal{T}_\mu}(D) f\rVert_{L^2_x} &\leq \lVertf\rVert_{L^2_x},
        \\
        \label{eq:est_on_tilbert_J_mu}
        \lVert\sqrt{\mathcal{T}_\mu}(D)J^\frac{1}{2}_\mu f\rVert_{L^2_x}  &\sim \lVertf\rVert_{L^2_x},
       \\                 
        \label{eq:J_mu_to_f_H_s}
       \lVertJ^\frac{1}{2}_\mu f\rVert_{H^s}^2 &\sim \lVertf\rVert_{H^s_x}^2 + \sqrt{\mu} \lVert|D|^\frac{1}{2} f\rVert_{H^s_x}^2,
    \intertext{and}
        \label{eq:est_on_tilbert_invers}
        \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D) f\rVert_{H^s_x}^2 &\sim \lVertf\rVert_{H^s_x}^2 + \sqrt{\mu} \lVert|D|^\frac{1}{2} f\rVert_{H^s_x}^2.
    \end{align}

\label{lem:riesz_transform}
    For $1<p<\infty$, it holds that
    \begin{align}\label{eq:riesz_transform_est}
        \lVertR_jf\rVert_{L^p_x} \lesssim \lVertf\rVert_{L^p_x}
    \end{align}
    for $j=1,2$ and
    \begin{align}\label{eq:riesz_transform_property}
        |D| &= \mathbf{R} \cdot \nabla.
    \end{align}

\label{prop:energy_ests_d_2}
    Let $s >2$, $\epsilon,\mu \in(0,1]$, $r\geq s+1$, and $(\eta,\mathbf{v}) \in C([0,T];V_\mu^r(\mathbb{R}^2))$ be a solution to \eqref{eq:compact_eq_d_2} on a time interval $[0,T]$ for some $T>0$. Assume that there exists  a $h_0\in(0,1)$ such that
    \begin{align}\label{eq:assump_eta1_v1_d_2}
        h_0 - 1 \leq  \epsilon \eta(x,t) \  \text{ for all } (x,t)\in \mathbb{R}^2 \times [0,T] .
    \end{align}
    Additionally, assume that $\mathrm{curl}\:  \mathbf{v} = 0$.
    Then, the energy defined in \eqref{eq:energy_d_2} satisfies
    \begin{align}\label{eq:energy_sim_V_d_2} 
       h_0\lVert(\eta,\mathbf{v})(t)\rVert_{V_\mu^s}^2 \lesssim E_s(\mathbf{U}(t)) \lesssim H(t) \lVert(\eta,\mathbf{v})(t)\rVert_{V_\mu^s}^2 
    \end{align}
    and
    \begin{align}
        \label{eq:derivative_energy_d_2}
        \frac{\:\mathrm{d}}{\:\mathrm{d} t} E_s(\mathbf{U}(t)) &\lesssim  \epsilon H(t) \mathcal{P}(t)  E_s(\mathbf{U}(t))
    \end{align}
    for all $t\in (0,T)$, where
    \begin{align}\label{eq:P}
        \mathcal{P}(t) &:= \lVert\nabla \eta(t)\rVert_{L^\infty_x} +\lVert\nabla \mathbf{v}(t)\rVert_{L^\infty_x}  + \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)\nabla \mathbf{v}(t)\rVert_{L^\infty_x} 
        \intertext{and}
        H(t) &:= 1+ \epsilon\lVert(\eta,\mathbf{v})(t)\rVert_{L^\infty_x \times L^\infty_x}.
    \end{align}

To verify that $E_s(\mathbf{U})$ defined in \eqref{eq:energy_d_2} satisfies the equivalence \eqref{eq:energy_sim_V_d_2}. The non-cavitation condition \eqref{eq:assump_eta1_v1_d_2} and \eqref{eq:equivalent_norm_Vsmu} implies
    \begin{align*}
        E_s(\mathbf{U})                                                                                                                                                                            
        &\geq  \lVert\eta\rVert_{H^s_x}^2 + h_0  \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}\rVert_{H^s_x}^2 

        \gtrsim h_0 \lVert(\eta,\mathbf{v})\rVert^2_{V^s_\mu}.
    \end{align*}
    We obtain the reverse inequality by H\"{o}lder's inequality and the estimate \eqref{eq:equivalent_norm_Vsmu}. Indeed, we obtain 
    \begin{align*}
         E_s(\mathbf{U}) &\leq \lVert\eta\rVert_{H^s_x}^2 + (1+\epsilon\lVert\eta\rVert_{L^\infty_x} ) \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathbf{v}\rVert_{H^s_x}^2 
         \lesssim H(t) \lVert(\eta,\mathbf{v})\rVert^2_{V^s_\mu}.
    \end{align*}
    We will now prove \eqref{eq:derivative_energy_d_2} by using \eqref{eq:energy_d_2}. From the fact that $\mathcal{Q}(\mathbf{U},D)$ is symmetric and \eqref{eq:compact_eq_d_2}, we can write
    \begin{align}\label{eq:est_energy_d_2}
         \frac{1}{2} \frac{\:\mathrm{d}}{\:\mathrm{d} t} E_s(\mathbf{U}) &= - \big({J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathcal{M}(\mathbf{U},D) \mathbf{U}},{\mathcal{Q}(\mathbf{U},D)J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathbf{U}}\big)_{L^2_x} \\ \notag
         &+ \frac{1}{2} \big({J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathbf{U}},{(\partial_t\mathcal{Q}(\mathbf{U},D)) J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathbf{U}}\big)_{L^2_x}\\ \notag
         &=: -\mathcal{I} + \mathcal{II}.
    \end{align}
    \addtocontents{toc}{\gobblefive}\subsubsection*{\underline{Control of $\mathcal{I}$}}
    With the definitions \eqref{eq:M_d_2}--\eqref{eq:Q_d_2}, the term $\mathcal{I}$ can be written as
    \begin{align*}
        \mathcal{I} &= \epsilon\big({J^s (\mathbf{v}\cdot \nabla \eta)},{J^s \eta}\big)_{L^2_x} 
        + \big({J^s \big((1+\epsilon\eta) \nabla \cdot \mathbf{v}\big)},{J^s \eta}\big)_{L^2_x} \\
        &+ \big({J^s \sqrt{\mathcal{T}_\mu}(D) \nabla \eta },{(1+\epsilon\eta)J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathbf{v} }\big)_{L^2_x} \\
        &+\epsilon \big({J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \big( (\mathbf{v}\cdot \nabla) \mathbf{v}\big)},{ (1+\epsilon\eta)J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)\mathbf{v}}\big)_{L^2_x} \\
        &=: \mathcal{A}_{11} +\mathcal{A}_{12} + \mathcal{A}_{21} + \mathcal{A}_{22}. 
    \end{align*}
    \addtocontents{toc}{\gobblefive}\subsubsection*{Estimating $\mathcal{A}_{11}$} We decompose
    \begin{align*}
        \mathcal{A}_{11} &= \epsilon  \big({[J^s,\mathbf{v}]\cdot\nabla \eta },{J^s \eta}\big)_{L^2_x} +  \epsilon  \big({\mathbf{v}\cdot J^s \nabla \eta },{J^s \eta}\big)_{L^2_x}\\
        &=: \mathcal{A}_{11}^1 + \mathcal{A}_{11}^2.
    \end{align*}
    From the Cauchy-Schwarz inequality and the Kato-Ponce commutator estimate \eqref{eq:kato_ponce}, we have
    \begin{align*}
        |\mathcal{A}_{11}^1|                                                                                                  
        &\leq \epsilon \sum_{j=1,2}  \lVert[J^s,v_j]\partial_{x_j} \eta\rVert_{L^2_x} \lVert\eta\rVert_{H^s_x}\\
        &\lesssim  \epsilon \sum_{j=1,2}\Big(\lVert\nabla v_j\rVert_{L^\infty_x} \lVert\eta \rVert_{H^s_x} + \lVert\partial_{x_j} \eta\rVert_{L^\infty_x} \lVertv_j \rVert_{H^s_x}\Big) \lVert\eta\rVert_{H^s_x} \\
        &\lesssim \epsilon \Big(\lVert\nabla \mathbf{v}\rVert_{L^\infty_x} + \lVert\nabla \eta\rVert_{L^\infty_x}\Big) \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align*}
    Next, the term $\mathcal{A}_{11}^2$ can be estimated from integration by parts and H\"{o}lder's inequality. This yields 
    \begin{align*}
        |\mathcal{A}_{11}^2| &\leq \frac{\epsilon}{2} \lVert\nabla \cdot \mathbf{v}\rVert_{L^\infty_x}  \lVertJ^s \eta \rVert^2_{L^2_x} \leq \epsilon \lVert\nabla \mathbf{v}\rVert_{L^\infty_x} \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align*}
    Combining these estimates gives us
    \begin{align}\label{eq:est_A11_d_2}
        |\mathcal{A}_{11} | \lesssim \epsilon \big( \lVert\nabla \eta\rVert_{L^\infty_x} +\lVert\nabla \mathbf{v}\rVert_{L^\infty_x}  \big) \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align}
    \addtocontents{toc}{\gobblefive}\subsubsection*{Estimating $\mathcal{A}_{12} + \mathcal{A}_{21}$}
    We can write  $\mathcal{A}_{12}$ as
    \begin{align*}
    \mathcal{A}_{12} &= \epsilon
        \big({[J^s  ,\eta] \nabla \cdot  \mathbf{v} },{J^s \eta  }\big)_{L^2_x}
        + \big({(1+\epsilon \eta) J^s \nabla \cdot  \mathbf{v} },{J^s \eta  }\big)_{L^2_x}\\
        &=: \mathcal{A}_{12}^1 + \mathcal{A}_{12}^2.
    \end{align*}
    From the Cauchy-Schwarz inequality and the Kato-Ponce commutator estimate \eqref{eq:kato_ponce}, we obtain
    \begin{align*}
        |\mathcal{A}_{12}^1| &\leq \epsilon
        \lVert[J^s,\eta] \nabla \cdot  \mathbf{v} \rVert_{L^2_x} \lVertJ^s \eta  \rVert_{L^2_x}\\

        &\lesssim  \epsilon \big(\lVert\nabla \mathbf{v}\rVert_{L^\infty_x} + \lVert\nabla \eta\rVert_{L^\infty_x}\big) \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align*}
    We cannot estimate $\mathcal{A}_{12}^{2}$ on its own, but it will be absorbed by $\mathcal{A}_{21}$. Next,  we observe from integration by parts  that
    \begin{align*}                   
        \mathcal{A}_{21} &= - \epsilon\big({J^s   \sqrt{\mathcal{T}_\mu}(D)  \eta },{\nabla\eta\cdot J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathbf{v}}\big)_{L^2_x} - \big({J^s\sqrt{\mathcal{T}_\mu}(D) \eta },{(1+\epsilon \eta)J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \nabla \cdot \mathbf{v}  }\big)_{L^2_x}\\
        &=: \mathcal{A}_{21}^1 + \mathcal{A}_{21}^2.
        \notag
    \end{align*}
    From H\"{o}lder's inequality, \eqref{eq:est_on_tilbert}, and \eqref{eq:equivalent_norm_Vsmu}, we obtain
    \begin{align*}
        |\mathcal{A}_{21}^1| &\leq \epsilon \lVert\nabla \eta\rVert_{L^\infty_x}\lVertJ^s \sqrt{\mathcal{T}_\mu}(D)   \eta \rVert_{L^2_x} \lVertJ^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}  \rVert_{L^2_x}\\

        &\lesssim \epsilon \lVert\nabla \eta\rVert_{L^\infty_x} \lVert(\eta,\mathbf{v})\rVert^2_{V^s_\mu}.
    \end{align*}
    For the term $\mathcal{A}_{21}^2$, we first need to rewrite it as
    \begin{align*}
        \mathcal{A}_{21}^2 &=\epsilon \big({J^s \sqrt{\mathcal{T}_\mu}(D)   \eta },{[J^s,\eta]   \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \nabla\cdot \mathbf{v}}\big)_{L^2_x}  - \big({J^s \sqrt{\mathcal{T}_\mu}(D)   \eta },{J^s( (1+\epsilon \eta)\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \nabla\cdot \mathbf{v} ) }\big)_{L^2_x} \\
        &= : \mathcal{A}_{21}^{2,1} +  \mathcal{A}_{21}^{2,2}.
    \end{align*}
    This approach is needed due to the fact that we cannot close the estimates with $\lVertJ^s \nabla\cdot \mathbf{v}\rVert_{L^\infty_x}$ or $\lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)\eta\rVert_{H^s_x}$ on the right-hand side. We will therefore use the commutator estimate \eqref{eq:commutator_est_tilbert2} to handle $\mathcal{A}_{21}^{2,2}$. We start by treating $\mathcal{A}_{21}^{2,1}$. From the Cauchy-Schwarz inequality, \eqref{eq:est_on_tilbert}, the Kato-Ponce commutator estimate \eqref{eq:kato_ponce}, and \eqref{eq:est_on_tilbert_invers}, we have
    \begin{align*}
        |\mathcal{A}_{21}^{2,1}| &\leq \epsilon \lVertJ^s \sqrt{\mathcal{T}_\mu}(D)  \eta \rVert_{L^2_x} \lVert[J^s,\eta]   \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \nabla \cdot \mathbf{v} \rVert_{L^2_x} \\

        &\lesssim \epsilon \lVert\eta\rVert_{H^s_x} \Big(
        \lVert\nabla \eta\rVert_{L^\infty_x} \lVertJ^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v} \rVert_{L^2_x} + \lVertJ^s \eta\rVert_{L^2_x} \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)   \nabla\cdot \mathbf{v} \rVert_{L^\infty_x} \Big) \\
        &\lesssim \epsilon \Big( \lVert\nabla \eta\rVert_{L^\infty_x} +\lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \nabla \mathbf{v} \rVert_{L^\infty_x} \Big) \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align*}
    Lastly, we look at the term $\mathcal{A}_{21}^{2,2}$.   We observe that
    \begin{align*}
        \mathcal{A}_{21}^{2,2}                                                                                                                                                       
        &=- \epsilon\big({J^s   \eta },{[\sqrt{\mathcal{T}_\mu}(D)J^s,\eta ]\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \nabla\cdot \mathbf{v}  }\big)_{L^2_x} - \big({J^s  \eta },{ (1+\epsilon \eta) J^s \nabla\cdot \mathbf{v}  }\big)_{L^2_x} \\
        &=:\mathcal{A}_{21}^{2,2,1} +  \mathcal{A}_{21}^{2,2,2}.
    \end{align*}
    The Cauchy-Schwarz inequality, the commutator estimate \eqref{eq:commutator_est_tilbert2}, and \eqref{eq:est_on_tilbert_invers} applied to  $\mathcal{A}_{21}^{2,2,1}$ yields
    \begin{align*}
        |\mathcal{A}_{21}^{2,2,1}| &\leq \epsilon \lVertJ^s  \eta \rVert_{L^2_x} \lVert[\sqrt{\mathcal{T}_\mu}(D)J^s,\eta ]\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \nabla\cdot \mathbf{v}  \rVert_{L^2_x}\\
        &\lesssim \epsilon \lVert\eta\rVert_{H^s_x} \Big( \lVert\nabla \eta\rVert_{L^\infty_x}\lVertJ^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}\rVert_{L^2_x} + \lVertJ^s \eta\rVert_{L^2_x}\lVert \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \nabla\cdot \mathbf{v}\rVert_{L^\infty_x} \Big)\\
        &\lesssim \epsilon \Big( \lVert\nabla \eta\rVert_{L^\infty_x} +\lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \nabla\cdot \mathbf{v} \rVert_{L^\infty_x} \Big) \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align*}
    We make the observation that $\mathcal{A}_{21}^{2,2,2} = - \mathcal{A}_{12}^{2}$. So we may gather the above estimates to obtain
    \begin{align}\label{eq:est_A12A21_d_2}
        |\mathcal{A}_{12} + \mathcal{A}_{21}| \lesssim \epsilon \Big( \lVert\nabla \eta\rVert_{L^\infty_x} + \lVert\nabla \mathbf{v}\rVert_{L^\infty_x} + \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \nabla \mathbf{v} \rVert_{L^\infty_x}\Big) \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align}


   \addtocontents{toc}{\gobblefive} \subsubsection*{Estimating $\mathcal{A}_{22}$} 
    We first observe that
    \begin{align*}                       
        (\mathbf{v} \cdot \nabla)\mathbf{v} = (v_1\partial_{x_1} v_1 + v_2 \partial_{x_2}v_1, v_1\partial_{x_1} v_2 + v_2 \partial_{x_2}v_2)^\mathrm{T}
    \end{align*}
    which allows us to write
    \begin{align*}                         
        \mathcal{A}_{22} &= \epsilon \sum_{j,\ell = 1,2} \big({J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) (v_j \partial_{x_j} v_\ell)},{ (1+\epsilon\eta)J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)v_\ell}\big)_{L^2_x}\\ \notag
        &=\epsilon \sum_{j,\ell = 1,2} \big({[J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) , v_j] \partial_{x_j} v_\ell},{ (1+\epsilon\eta)J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)v_\ell}\big)_{L^2_x} \\ \notag
        &+ \epsilon \sum_{j,\ell = 1,2} \big({v_jJ^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \partial_{x_j} v_\ell},{ (1+\epsilon\eta)J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)v_\ell}\big)_{L^2_x} \\ \notag
        &=: \mathcal{A}_{22}^1 + \mathcal{A}_{22}^2.
    \end{align*}
    With the help of H\"{o}lder's inequality, the commutator estimate \eqref{eq:commutator_est_tilbert_inv},  and \eqref{eq:J_mu_to_f_H_s}--\eqref{eq:est_on_tilbert_invers}, we have
    \begin{align*}
        |\mathcal{A}_{22}^1| &\leq \epsilon \sum_{j,\ell = 1,2}   \lVert[J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) ,v_j] \partial_{x_j} v_\ell \rVert_{L^2_x}(1+\epsilon \lVert\eta\rVert_{L^\infty_x})\lVertJ^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) v_\ell \rVert_{L^2_x}\\ \notag
        &\lesssim H(t)  \epsilon\sum_{j,\ell = 1,2}   \Big( \lVert\nabla v_j\rVert_{L^\infty_x}
        \lVertJ^\frac{1}{2}_\mu v_\ell\rVert_{H^s_x} + \lVert\partial_{x_j} v_\ell\rVert_{L^\infty_x}
        \lVertJ^\frac{1}{2}_\mu v_j\rVert_{H^s_x}  \Big)\lVertJ^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) v_\ell \rVert_{L^2_x}\\ \notag
        &\lesssim \epsilon H(t) \lVert\nabla \mathbf{v}\rVert_{L^\infty_x}\lVert(\eta, \mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align*}
    The term $\mathcal{A}_{22}^2$ is treated by integration by parts, H\"{o}lder's inequality,   and \eqref{eq:est_on_tilbert_invers}. This gives us
    \begin{align*}
        |\mathcal{A}_{22}^2| &\leq \frac{\epsilon}{2} \sum_{j,\ell = 1,2}\Big|  \big({ (\partial_{x_j}v_j)J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  v_\ell},{ (1+\epsilon\eta)J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)v_\ell}\big)_{L^2_x}\Big| \\
        &+ \frac{\epsilon^2 }{2} \sum_{j,\ell = 1,2}\Big| \big({ v_j J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) v_\ell },{(\partial_{x_j} \eta) J^s \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) v_\ell  }\big)_{L^2_x}\Big|\\
        &\lesssim  \epsilon H(t)\Big(\lVert\nabla \mathbf{v}\rVert_{L^\infty_x}+\lVert\nabla \eta\rVert_{L^\infty_x}\Big)\lVert(\eta, \mathbf{v})\rVert_{V^s_\mu}^2. 
    \end{align*}
    We gather the estimates for $\mathcal{A}_{22}^1$ and $\mathcal{A}_{22}^2$ to obtain
    \begin{align}\label{eq:est_A22_d_2}
        |\mathcal{A}_{22}| &\lesssim  \epsilon H(t)\Big(\lVert\nabla \mathbf{v}\rVert_{L^\infty_x}+ \lVert\nabla \eta\rVert_{L^\infty_x}\Big)\lVert(\eta, \mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align}
    Combining \eqref{eq:est_A11_d_2}--\eqref{eq:est_A22_d_2} yields
    \begin{align}\label{eq:mathcal_I_d_2}
        |\mathcal{I}| \lesssim \epsilon  H(t) \Big( \lVert\nabla \eta\rVert_{L^\infty_x} + \lVert\nabla \mathbf{v}\rVert_{L^\infty_x} + \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)\nabla \mathbf{v} \rVert_{L^\infty_x}\Big) \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align}
    \addtocontents{toc}{\gobblefive}\subsubsection*{\underline{Control of $\mathcal{II}$}}
    From \eqref{eq:compact_eq_d_2} and \eqref{eq:Q_d_2}, we can write
    \begin{align*}
       \mathcal{II} &=\frac{\epsilon}{2} \big({J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}},{(\partial_t \eta) J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}}\big)_{L^2_x}\\
       &= -\frac{\epsilon}{2} \big({J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}},{(\nabla \cdot \mathbf{v}) J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}}\big)_{L^2_x} -\frac{\epsilon^2}{2} \big({J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}},{(\nabla\cdot(\eta  \mathbf{v})) J^s\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)  \mathbf{v}}\big)_{L^2_x}.
    \end{align*}
    Then from H\"{o}lder's inequality and \eqref{eq:equivalent_norm_Vsmu}, we obtain
    \begin{align}\label{eq:mathcal_II_d_2}
        |\mathcal{II}|&\lesssim \epsilon \Big(\lVert\nabla \eta\rVert_{L^\infty_x} + \lVert\nabla \mathbf{v}\rVert_{L^\infty_x}\Big) \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu}^2.
    \end{align}
    Combining \eqref{eq:est_energy_d_2} with \eqref{eq:mathcal_I_d_2}--\eqref{eq:mathcal_II_d_2} gives us \eqref{eq:derivative_energy_d_2}, which concludes this proof.

\label{cor:wb_gron}
     Let $s >2$, $\epsilon,\mu\in(0,1]$, and  $T>0$. Assume that there exists  a $h_0\in(0,1)$ such that
    \begin{align}\label{eq:assump_eta1_v1_d_2_part2}
        h_0 - 1 \leq  \epsilon \eta(x,t) \  \text{ for all } (x,t)\in \mathbb{R}^2 \times [0,T]
    \end{align}
    and that $\mathrm{curl}\:  \mathbf{v} = 0$.
    Then, for any solution $(\eta,\mathbf{v}) \in C([0,T];V_\mu^s(\mathbb{R}^2))$ to \eqref{eq:compact_eq_d_2} on $[0,T]$ with $(\eta(0),\mathbf{v}(0))=(\eta_0,\mathbf{v}_0)$ we have
     \begin{equation}\label{eq:gronwall_wb}
         \lVert(\eta,\mathbf{v})(t)\rVert_{V_\mu^s}^2
         \lesssim H(t) h_0^{-1}
         \mathrm{e}^{c  \epsilon \int_0^tH(\tau) \mathcal{P}(\tau) \!\:\mathrm{d} \tau} \lVert(\eta_0,\mathbf{v}_0)\rVert_{V_\mu^s}^2
     \end{equation}
     for $t\in [0,T]$, where 
     \begin{align*}
         \mathcal{P}(t) &= \lVert\nabla \eta(t)\rVert_{L^\infty_x} +\lVert\nabla \mathbf{v}(t)\rVert_{L^\infty_x}  + \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)\nabla \mathbf{v}(t)\rVert_{L^\infty_x} 
          \intertext{and}
        H(t) &= 1+ \epsilon\lVert(\eta,\mathbf{v})(t)\rVert_{L^\infty_x \times L^\infty_x}.
     \end{align*}

\label{prop:boundedness_eta_v_d_2}
    Let $\epsilon,\mu\in (0,1]$, $r>\frac{9}{4}$, and $T>0$. Let $(\eta,\mathbf{v}) \in C([0,T];V_\mu^{r}(\mathbb{R}^2))$ be a solution to \eqref{eq:compact_eq_d_2}. 
    Then
    \begin{align*}
        \mathcal{P} := \lVert\nabla \eta\rVert_{L^\infty_x} +\lVert\nabla \mathbf{v}\rVert_{L^\infty_x}  + \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)\nabla \mathbf{v}\rVert_{L^\infty_x} 
    \end{align*}
    satisfies
    \begin{align}                               

       \label{eq:est_eta_desired_Dhalf_d_2}
      \lVert\mathcal{P}\rVert_{L^2(0,T)} &\lesssim \mu^{(-\frac{1}{6})^+ }   T^{\frac{1}{6}^+}  \lVert(\eta,\mathbf{v})\rVert_{L^\infty_TV^{r}_\mu} +  \epsilon  \mu^{(-\frac{1}{3})^+}  T^{\frac{5}{6}^+} \lVert(\eta,\mathbf{v})\rVert_{L^\infty_T V^{r}_\mu}^2.



    \end{align}

From \eqref{eq:def_eta_and_v_d_2}, we obtain
   \begin{align*}
        \lVert\nabla\eta\rVert_{L^2_TL^\infty_x} &= \lVert \nabla (u^+ + u^-) \rVert_{L^2_TL^\infty_x} \\ \notag
        &\leq \lVert\nabla u^+\rVert_{L^2_TL^\infty_x}  + \lVert \nabla u^-\rVert_{L^2_TL^\infty_x}\\ \notag
        &=: \sum_\pm  \lVert \nabla u^\pm \rVert_{L^2_TL^\infty_x}. 
   \end{align*}
   With the help of \eqref{Refined:2d} in Corollary \ref{cor:refined_strichartz_d_1} for  $u= \nabla u^\pm$ and $F =  -i\frac{\epsilon}{2}\nabla \mathcal{B}^\pm (\eta,\mathbf{v})$ (with $\mathcal{B}^\pm (\eta,\mathbf{v})$ defined in \eqref{eq:G_nonlin}), we obtain
    \begin{align}\label{eq:est2_eta_d_2}
        \lVert\nabla \eta\rVert_{L^2_TL^\infty_x} &\lesssim \mu^{-\frac{1}{6} + \frac{5\theta}{36}} T^{\frac{1}{6} + \frac{5\theta}{18}} \sum_\pm \Big( \lVertJ^{\theta} |D|u^\pm\rVert_{L_T^\infty L_x^2}
+ \lVert\vert D \vert^{\frac{3}{2}-\frac{\theta}{3}} J^{2\theta} J_\mu^{\frac{3}{4}}  u^\pm\rVert_{L_T^\infty L_x^2}\Big)
  \\ \notag
 & + \mu^{-\frac{1}{3}+\frac{\theta}{9}} T^{\frac{1}{3}+\frac{2\theta}{9}} \sum_\pm\lVert\vert D \vert^{\frac{1}{2}-\frac{\theta}{3}} J^\theta J_\mu^{\frac{3}{4}} \mathcal{B}^\pm (\eta,\mathbf{v})\rVert_{L_T^2 L_x^2}\\ \notag
  &=:\mu^{-\frac{1}{6}+\frac{5\theta}{36}} T^{\frac{1}{6}+\frac{5\theta}{18}} I_1 +\mu^{-\frac{1}{3}+\frac{\theta}{9}} T^{\frac{1}{3}+\frac{2\theta}{9}}  I_2.
    \end{align}
    for $\theta>0$ small. Using \eqref{eq:def_uplus_uminus_d2}, \eqref{eq:riesz_transform_est}, and \eqref{eq:equivalent_norm_Vsmu} implies
    \begin{align}\label{eq:est2_eta_d_2_part_2}
        I_1 &\lesssim  \lVertJ^\frac{3}{4}_\mu J^{\frac{3}{2} +\frac{5\theta}{3}} \eta\rVert_{L^\infty_TL^2_x} + \lVertJ^\frac{3}{4}_\mu J^{\frac{3}{2} +\frac{5\theta}{3}} \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \mathbf{R} \cdot  \mathbf{v} \rVert_{L^\infty_TL^2_x}\\ \notag

        &\lesssim \lVert(\eta,\mathbf{v})\rVert_{L^\infty_TV^{r}_\mu}
    \end{align}
    for $r>\frac{9}{4}$. To estimate $I_2$ in \eqref{eq:est2_eta_d_2}, we use \eqref{eq:est_on_tilbert_invers}, H\"{o}lder's inequality, the Kato-Ponce inequality \eqref{eq:kato_ponce_ineq}, a Sobolev embedding, and \eqref{eq:J_mu_to_f_H_s}. This yields
    \begin{align}\label{eq:est2_eta_d_2_part_3}
        I_2 &\lesssim \lVertJ^\frac{3}{4}_\mu J^{\theta} |D|^{\frac{3}{2}-\frac{\theta}{3}} (\eta \mathbf{v})\rVert_{L^2_TL^2_x} +  \lVertJ^\frac{3}{4}_\mu J^\theta   \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) |D|^{\frac{3}{2}-\frac{\theta}{3}}(|\mathbf{v}|^2)\rVert_{L^2_TL^2_x} \\ \notag
        &\lesssim T^\frac{1}{2}\Big( \lVertJ^{r} (\eta\mathbf{v})\rVert_{L^\infty_TL^2_x} +  \lVertJ^{r} (|\mathbf{v}|^2)\rVert_{L^\infty_TL^2_x} +  \mu^\frac{1}{4}\lVertJ^{r+\frac{1}{2}}(|\mathbf{v}|^2)\rVert_{L^\infty_TL^2_x}\Big) \\ \notag

        &\lesssim T^\frac{1}{2} \lVert(\eta,\mathbf{v})\rVert_{V^{r}_\mu}^2
    \end{align}
    for $r>\frac{9}{4}$. Gathering the estimates of $I_1$ and $I_2$ in \eqref{eq:est2_eta_d_2} gives us \eqref{eq:est_eta_desired_Dhalf_d_2}.
    \\
    \indent Next, from \eqref{eq:def_eta_and_v_d_2}, we have
    \begin{align*}                             
        \lVert\nabla \mathbf{v}\rVert_{L^2_TL^\infty_x} +  \lVert \mathcal{T}_{\mu}^{-\frac{1}{2}}(D) \nabla \mathbf{v}\rVert_{L^2_TL^\infty_x}                                                                                                

        &\leq \sum_\pm  \lVert \sqrt{\mathcal{T}_\mu}(D) \nabla\mathbf{R} u^\pm \rVert_{L^2_TL^\infty_x} + \sum_\pm  \lVert\nabla\mathbf{R} u^\pm \rVert_{L^2_TL^\infty_x}.


    \end{align*}
    Utilizing \eqref{Refined:2d} in Corollary  \ref{cor:refined_strichartz_d_1}, \eqref{eq:est_on_tilbert}, and                                                                                                                                                                                          
    \eqref{eq:riesz_transform_est}, we obtain the estimate in the same way as \eqref{eq:est2_eta_d_2}--\eqref{eq:est2_eta_d_2_part_3}.

We first recall a local well-posedness result for \eqref{eq:whitham_boussinesq} and \eqref{eq:whitham_boussinesq_d2}.
\begin{thm}\label{thm:paulsen}
    For $d\in \{1,2\}$ with $s>\frac{d}{2}+1$ and $\epsilon,\mu \in (0,1]$. Assume that $(\eta_0,\mathbf{v}_0)\in V^s_\mu(\mathbb{R}^d)$ satisfy the non-cavitation condition \eqref{eq:noncav}.  If $d=2$, we additionally assume that $\mathrm{curl}\: \mathbf{v}_0 = 0$.  Then there exists a positive time 
    \begin{equation*}
         T = T(\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu})= \frac{1}{ c(d,s,h_0,H_0)  \lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}} 
    \end{equation*}
   with $H_0 = 1+ \epsilon\lVert(\eta_0,\mathbf{v}_0)\rVert_{L^\infty_x\times L^\infty_x}$    
    such that \eqref{eq:whitham_boussinesq} and \eqref{eq:whitham_boussinesq_d2} have a unique solution
    \begin{align*}
        (\eta,\mathbf{v}) \in C([0,T];V^s_\mu(\mathbb{R}^d) ) \cap C^1([0,T];V^{s-1}_\mu(\mathbb{R}^d) )
    \end{align*}
    that satisfies 
    \begin{align*}
        \sup_{t\in [0,T]} \lVert (\eta,\mathbf{v})\rVert_{V^s_\mu} \lesssim \lVert (\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}.
    \end{align*}
    Here, the implicit constant depends on $h_0$ and $H_0$.     Additionally, the flow map is continuous with respect to the initial data. Furthermore, higher regularity persists. That is, if $(\eta_0,\mathbf{v}_0) \in V^r_\mu(\mathbb{R}^d)$ for some $r > s$, then $(\eta,\mathbf{v})$ belongs to $C([0, T ] ; V^r_\mu(\mathbb{R}^d))$ (with the same $T$).
\end{thm}
\begin{remark}
    The above theorem was proved on the timescale $1/\epsilon$  under the condition 
\begin{align*}
        0<\epsilon c \lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu} \leq 1
\end{align*}
for $s>\frac{d}{2}+1$ in \cite[Theorem 1.11]{Paulsen2022}. However, one can use the same arguments as in the proof of Lemma \ref{lem:bootstrap_wb} below, where one has to substitute the refined Strichartz estimates (Proposition \ref{prop:boundedness_eta_v_d_2}) with a classical Sobolev embedding to obtain the well-posedness result for arbitrary data.
\end{remark}






It will suffice to show that the solution exists on the timescale $\epsilon^{-\frac{5}{4}} (\mu/\epsilon)^{\frac{1}{4}^-}$ to complete the proof of  Theorem \ref{thm:wellposedness_WB} as the rest follows by  Theorem \ref{thm:paulsen}. Indeed, the uniqueness, continuous dependence on the data, and persistence of higher regularity are local-in-time properties (see Remarks \ref{rem:w_rem1}--\ref{rem:w_rem3}).










   From Theorem \ref{thm:paulsen}, it follows that an initial datum $(\eta_0,\mathbf{v}_0)\in V^s_\mu(\mathbb{R}^2)$, for $s>2$, generate a solution to \eqref{eq:compact_eq_d_2}, $(\eta,\mathbf{v}) \in C([0,T^\ast);V^s_\mu(\mathbb{R}^2))$, where $T^\ast\geq T(\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu})$ is the maximal time of existence. Since $T$ is a decreasing function of its argument, we may deduce classically that the solution of \eqref{eq:compact_eq_d_2} satisfies the blow-up alternative:
\begin{align}\label{eq:BA_d2}
    \text{If } \ \ T^\ast <\infty, \text{ then } \limsup_{t\nearrow T^\ast} \lVert(\eta,\mathbf{v})(t)\rVert_{V^s_\mu} = \infty.
\end{align}






\begin{lem}\label{lem:bootstrap_wb}
    Let $s>\frac{9}{4}$ and $\epsilon,\mu\in (0,1]$. 




    Then there exists a time
    \begin{align}\label{eq:def_T_0_d_2}
        T_1 = \epsilon^{-\frac{5}{4}}  \Big(\frac{\mu}{\epsilon}\Big)^{\frac{1}{4}^-} (C_1)^{-1}\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}^{(-\frac{3}{2})^+}
    \end{align}
    such that $T^\ast > T_1$ and
    \begin{align*}                       
        \sup_{t\in [0,T_1]}\lVert(\eta,\mathbf{v})(t)\rVert_{V^s_\mu} \leq 5 c \sqrt{\frac{H_0}{h_0}}  \lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}
    \end{align*}
   where 
   $H_0 = 1+ \epsilon\lVert(\eta_0,\mathbf{v}_0)\rVert_{L^\infty_x\times L^\infty_x}$, $h_0 \in (0,1)$, and  $C_1 =C_1(h_0,H_0)$ is a positive constant fixed in the proof. 
\end{lem}


\begin{proof}
    We define
    \begin{align}\label{eq:T_tilde_nu_d_2}
        \Tilde{T} := \sup \{ T \in (0,T^\ast) : \sup_{t\in [0,T]} \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu} \leq 5 c \sqrt{\frac{H_0}{h_0}} \lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu} \}
    \end{align}
    for some $c>0$.    To obtain the result, we will argue by contradiction by assuming that $\Tilde{T} \leq T_1$. 
    \\
    \indent 
    For simplicity in notation, we denote 
    \begin{align*}
        A(t) &:= \lVert(\eta,\mathbf v)(t)\rVert_{V^s_\mu}^2,\\
        H(t) &:=  1 + \epsilon \lVert(\eta,\mathbf{v})(t)\rVert_{L^\infty_x \times L^\infty_x},
        \intertext{and}
     h(t) &:= \inf_{x \in \mathbb{R}^2} \left\{ 1+ \epsilon\eta(x,t) \right\}.
\end{align*}
    We also write $A(0) := A_0$, $H(0) := H_0$, and $h(0) := h_0$, where the non-cavitation condition can then be restated as $h_0 > 0$. We fix $T_2 \in (0,\Tilde{T})$ and claim that
        \begin{equation}\label{Apriori}
       h(t) \geq \frac{h_0}{2}
        \quad \text{and} \quad
       \sup_{t\in [0,T_2]} H(t) \leq 2H_0




    \end{equation}
     for all $t \in [0,T_2]$ implying that the condition \eqref{eq:assump_eta1_v1_d_2_part2} holds.   Then, using \eqref{eq:gronwall_wb}, the Cauchy-Schwarz inequality in time, and  the claim \eqref{Apriori}  yields
    \[
    A(t)
  \leq 4c_2 \frac{H_0}{h_0} A_0
  \mathrm{e}^{c H_0 \epsilon T_2^\frac{1}{2}\lVert\mathcal{P}\rVert_{L^2(0,T_2)}} ,
\]
where $c_2>0$ is the constant in \eqref{eq:gronwall_wb} and $\mathcal{P}(t) = \lVert\nabla \eta(t)\rVert_{L^\infty_x} +\lVert\nabla \mathbf{v}(t)\rVert_{L^\infty_x}  + \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)\nabla \mathbf{v}(t)\rVert_{L^\infty_x}$.
 From \eqref{eq:est_eta_desired_Dhalf_d_2} and the assumption $T_2 < \Tilde{T}\leq T_1$, it follows that, if $s > \frac{9}{4}$, then
\begin{align*}
     \epsilon  T_2^\frac{1}{2} \lVert\mathcal{P}\rVert_{L^2(0,T_2)} &\lesssim  \epsilon
  \mu^{(-\frac{1}{6})^+} T_2^{\frac{2}{3}^+}\lVertA\rVert_{L^\infty(0,T_2)}^{\frac{1}{2}}
  + \epsilon^2  \mu^{(-\frac{1}{3})^+} T_2^{\frac{4}{3}^+} \lVertA\rVert_{L^\infty(0,T_2)} \\
  &\lesssim  \epsilon
  \mu^{(-\frac{1}{6})^+} T_1^{\frac{2}{3}^+} \sqrt{\frac{H_0}{h_0} A_0}
  +  \epsilon^2  \mu^{(-\frac{1}{3})^+} T_1^{\frac{4}{3}^+}  \frac{H_0}{h_0} A_0\\
  &=: \delta + \delta^2,
\end{align*}
where 
\begin{align}\label{eq:delta}
    \delta = c \epsilon \mu^{(-\frac{1}{6})^+} T_1^{\frac{2}{3}^+} \sqrt{\frac{H_0}{h_0} A_0}.
\end{align}
Gathering the above, we have
\begin{equation}\label{A-est}
    A(t) \le 4c_2\frac{H_0}{h_0} A_0 \mathrm{e}^{ \delta + \delta^2}
\end{equation}
for all $t\in [0,T_2]$. We choose $T_1 > 0$  so small that
\begin{equation}\label{delta-condition}
4 c \delta \leq  \frac{4 c H_0}{h_0} \delta < \frac{\log 2}{2},
\end{equation}
that is, 
\begin{align*}
     \frac{ 5c H_0}{h_0} c \epsilon \mu^{(-\frac{1}{6})^+} T_1^{\frac{2}{3}^+} \sqrt{ \frac{H_0}{h_0} A_0} < \frac{\log 2}{2},
\end{align*}
which is the same as \eqref{eq:def_T_0_d_2}. We remark that \eqref{delta-condition} implies $\delta < 1$, so that $\delta+\delta^2 < 2\delta$. This gives us 
\begin{align*}
      A(t) \le 8c_2\frac{H_0}{h_0} A_0 
\end{align*}
for all $t\in [0,T_2]$ implying
\begin{align*}
     \lVert(\eta,\mathbf{v})(t)\rVert_{V^s_\mu} \leq 3\sqrt{c_2\frac{H_0}{h_0}}\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}.
\end{align*}
Consequently, we have from the blow-up alternative \eqref{eq:BA_d2} that $T_2< T^\ast$.                                                                       
From \eqref{eq:BA_d2}, it follows that the solution $(\eta,\mathbf{v})$ is continuous for $t\in [0,T^\ast)$. Thus, there exists a time $\tau \in [\Tilde{T},T^\ast)$ such that 
    \begin{align*}
        \lVert(\eta,\mathbf{v})(\tau)\rVert_{V^s_\mu} \leq 4  \sqrt{c_2\frac{H_0}{h_0}}\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu},
    \end{align*}
    which contradicts with the definition of $\Tilde{T}$ \eqref{eq:T_tilde_nu_d_2}. Hence, $T_1 < \Tilde{T}$, where $T_1$ is as seen in \eqref{eq:def_T_0_d_2}.
    \subsubsection*{\underline{Proof of the claim \eqref{Apriori}}}
    We start by verifying the last inequality of \eqref{Apriori}. From the fundamental theorem of calculus  and H\"{o}lder's inequality in time, we have that
    \begin{align*}
      H(t)  =  1+ \epsilon\lVert(\eta,\mathbf{v})(t)\rVert_{L^\infty_x \times L^\infty_x} &\leq  H_0 +  \epsilon T_2^\frac{1}{2} \Big(
        \lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x} + 
        \lVert\partial_t\mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}\Big). 
    \end{align*}
      From \eqref{eq:compact_eq_d_2}, Proposition \ref{prop:boundedness_eta_v_d_2}, and $T_2<\Tilde{T}$, we obtain
      \begin{align*}
          \epsilon T_2^\frac{1}{2} \lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x} &\leq \epsilon T_2^\frac{1}{2}  \Big(\lVert\nabla \cdot \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x} + \epsilon  \lVert\nabla \eta\rVert_{L^2_{T_2} L^\infty_x}\lVert\mathbf{v}\rVert_{L^\infty_{T_2} L^\infty_x}
      + \epsilon   \lVert\nabla \cdot \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}\lVert\eta\rVert_{L^\infty_{T_2} L^\infty_x}\Big) \\
      &\leq \epsilon T_2^\frac{1}{2} \lVertH\rVert_{L^\infty(0,T_2)}\lVert\mathcal{P}\rVert_{L^2(0,T_2)}\\
      &\leq 2\lVertH\rVert_{L^\infty(0,T_2)} \delta
      \end{align*}
       for $s>\frac{9}{4}$,    where $\delta$ is defined in \eqref{eq:delta}. Next, \eqref{eq:compact_eq_d_2} and 
    \begin{align*}
        (\mathbf{v} \cdot \nabla)\mathbf{v} = (v_1\partial_{x_1} v_1 + v_2 \partial_{x_2}v_1, v_1\partial_{x_1} v_2 + v_2 \partial_{x_2}v_2)^\mathrm{T}
    \end{align*}
    yields
    \begin{align*}
        \epsilon T_2^\frac{1}{2} \lVert\partial_t\mathbf{v}\rVert_{L^2_{T_2} L^\infty_x} &\leq \lVert\mathcal{T}_\mu(D)\nabla \eta\rVert_{L^2_{T_2} L^\infty_x} +  \epsilon \lVert(\mathbf{v}\cdot\nabla) \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}
        \\
        &\leq  \lVertH\rVert_{L^\infty(0,T_2)}\Big( \lVert\mathcal{T}_\mu(D)\nabla \eta\rVert_{L^2_{T_2} L^\infty_x} +  \lVert\nabla \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}\Big).
    \end{align*}
    The first term can be estimated by slightly modifying the proof of $\lVert\nabla \eta\rVert_{L^2_{T_2} L^\infty_x}$ in Proposition \ref{prop:boundedness_eta_v_d_2}, where one has to utilize \eqref{eq:est_on_tilbert}. Then from Proposition \ref{prop:boundedness_eta_v_d_2}, we obtain
    \begin{align*}
       \epsilon T_2^\frac{1}{2} \lVert\partial_t\mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}  &\leq   2\lVertH\rVert_{L^\infty(0,T_2)} \delta
    \end{align*} 
     for $s>\frac{9}{4}$.    Gathering the above calculations gives us
    \begin{align*}
        (1-4\delta) \lVertH\rVert_{L^\infty(0,T_2)} \leq H_0,
    \end{align*}
    which requires
        \begin{align*}
         4  \delta < \frac12,
     \end{align*}
     but this is satisfied due to \eqref{delta-condition}.
     \\
    \indent 
     Lastly, we will verify that $\eta$ satisfies the non-cavitation condition. From the fundamental theorem of calculus, the non-cavitation condition on $\eta_0$ \eqref{eq:noncav}, and H\"{o}lder's inequality, we obtain
    \begin{align*}                                 
        1+ \epsilon\eta(x,t) = 1 + \epsilon \eta_0+ \epsilon \int_0^t \partial_t\eta(x,s) \:\mathrm{d} s  \geq  h_0 - \epsilon T_2^{\frac{1}{2}} \lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x}
    \end{align*}
    for all $(x,t)\in \mathbb{R}^2 \times [0,T_2]$. It is enough to prove that
    \begin{align*}
       \epsilon T_2^{\frac{1}{2}} \lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x}  \leq \frac{h_0}{2}.
    \end{align*}
    From the first equation in \eqref{eq:whitham_boussinesq_d2}, H\"{o}lder's inequality, the second inequality in \eqref{Apriori} (verified above), Proposition \ref{prop:boundedness_eta_v_d_2}, and the assumption $T_2<\Tilde{T}\leq T_1$, we obtain
    \begin{align*}                                    
        \epsilon T_2^{\frac{1}{2}}\lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x} &\leq \lVert\nabla \cdot \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x} + \epsilon \lVert\nabla \eta\rVert_{L^2_{T_2} L^\infty_x}\lVert\mathbf{v}\rVert_{L^\infty_{T_2} L^\infty_x}
      + \epsilon \lVert\nabla \cdot \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}\lVert\eta\rVert_{L^\infty_{T_2} L^\infty_x} \\ \notag
        &\leq 2H_0  \epsilon T_2^{\frac{1}{2}}\lVert\mathcal{P}\rVert_{L^2(0,T_2)} \\ \notag
        &\leq 4cH_0 \delta
    \end{align*}
     for $s>\frac{9}{4}$. So, we need 
     \begin{align*}
         4c \frac{H_0}{h_0} \delta < \frac12
     \end{align*}
     to conclude, which holds by \eqref{delta-condition}.

    \renewcommand$\overset{\text{Lemma \ref{lem:bootstrap_wb}}}{\ensuremath{\Box}}${$\overset{\text{Lemma \ref{lem:bootstrap_wb}}}{\ensuremath{\Box}}$}
\end{proof}

\subsubsection*{Conclusion.}                                                                                                                                                                  
It remains to comment on the uniqueness, continuous dependence of the initial data, and the persistence of higher regularity. All these properties are known for some positive time by the local well-posedness result, Theorem \ref{thm:paulsen}, and they therefore extend to the larger time interval $[0,T_1]$ by standard arguments (see Remarks \ref{rem:w_rem1}--\ref{rem:w_rem3} for more details). This concludes the proof of the theorem for $d=2$.

\label{thm:paulsen}
    For $d\in \{1,2\}$ with $s>\frac{d}{2}+1$ and $\epsilon,\mu \in (0,1]$. Assume that $(\eta_0,\mathbf{v}_0)\in V^s_\mu(\mathbb{R}^d)$ satisfy the non-cavitation condition \eqref{eq:noncav}.  If $d=2$, we additionally assume that $\mathrm{curl}\: \mathbf{v}_0 = 0$.  Then there exists a positive time 
    \begin{equation*}
         T = T(\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu})= \frac{1}{ c(d,s,h_0,H_0)  \lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}} 
    \end{equation*}
   with $H_0 = 1+ \epsilon\lVert(\eta_0,\mathbf{v}_0)\rVert_{L^\infty_x\times L^\infty_x}$    
    such that \eqref{eq:whitham_boussinesq} and \eqref{eq:whitham_boussinesq_d2} have a unique solution
    \begin{align*}
        (\eta,\mathbf{v}) \in C([0,T];V^s_\mu(\mathbb{R}^d) ) \cap C^1([0,T];V^{s-1}_\mu(\mathbb{R}^d) )
    \end{align*}
    that satisfies 
    \begin{align*}
        \sup_{t\in [0,T]} \lVert (\eta,\mathbf{v})\rVert_{V^s_\mu} \lesssim \lVert (\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}.
    \end{align*}
    Here, the implicit constant depends on $h_0$ and $H_0$.     Additionally, the flow map is continuous with respect to the initial data. Furthermore, higher regularity persists. That is, if $(\eta_0,\mathbf{v}_0) \in V^r_\mu(\mathbb{R}^d)$ for some $r > s$, then $(\eta,\mathbf{v})$ belongs to $C([0, T ] ; V^r_\mu(\mathbb{R}^d))$ (with the same $T$).

The above theorem was proved on the timescale $1/\epsilon$  under the condition 
\begin{align*}
        0<\epsilon c \lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu} \leq 1
\end{align*}
for $s>\frac{d}{2}+1$ in \cite[Theorem 1.11]{Paulsen2022}. However, one can use the same arguments as in the proof of Lemma \ref{lem:bootstrap_wb} below, where one has to substitute the refined Strichartz estimates (Proposition \ref{prop:boundedness_eta_v_d_2}) with a classical Sobolev embedding to obtain the well-posedness result for arbitrary data.

\label{lem:bootstrap_wb}
    Let $s>\frac{9}{4}$ and $\epsilon,\mu\in (0,1]$. 




    Then there exists a time
    \begin{align}\label{eq:def_T_0_d_2}
        T_1 = \epsilon^{-\frac{5}{4}}  \Big(\frac{\mu}{\epsilon}\Big)^{\frac{1}{4}^-} (C_1)^{-1}\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}^{(-\frac{3}{2})^+}
    \end{align}
    such that $T^\ast > T_1$ and
    \begin{align*}                       
        \sup_{t\in [0,T_1]}\lVert(\eta,\mathbf{v})(t)\rVert_{V^s_\mu} \leq 5 c \sqrt{\frac{H_0}{h_0}}  \lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}
    \end{align*}
   where 
   $H_0 = 1+ \epsilon\lVert(\eta_0,\mathbf{v}_0)\rVert_{L^\infty_x\times L^\infty_x}$, $h_0 \in (0,1)$, and  $C_1 =C_1(h_0,H_0)$ is a positive constant fixed in the proof.

We define
    \begin{align}\label{eq:T_tilde_nu_d_2}
        \Tilde{T} := \sup \{ T \in (0,T^\ast) : \sup_{t\in [0,T]} \lVert(\eta,\mathbf{v})\rVert_{V^s_\mu} \leq 5 c \sqrt{\frac{H_0}{h_0}} \lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu} \}
    \end{align}
    for some $c>0$.    To obtain the result, we will argue by contradiction by assuming that $\Tilde{T} \leq T_1$. 
    \\
    \indent 
    For simplicity in notation, we denote 
    \begin{align*}
        A(t) &:= \lVert(\eta,\mathbf v)(t)\rVert_{V^s_\mu}^2,\\
        H(t) &:=  1 + \epsilon \lVert(\eta,\mathbf{v})(t)\rVert_{L^\infty_x \times L^\infty_x},
        \intertext{and}
     h(t) &:= \inf_{x \in \mathbb{R}^2} \left\{ 1+ \epsilon\eta(x,t) \right\}.
\end{align*}
    We also write $A(0) := A_0$, $H(0) := H_0$, and $h(0) := h_0$, where the non-cavitation condition can then be restated as $h_0 > 0$. We fix $T_2 \in (0,\Tilde{T})$ and claim that
        \begin{equation}\label{Apriori}
       h(t) \geq \frac{h_0}{2}
        \quad \text{and} \quad
       \sup_{t\in [0,T_2]} H(t) \leq 2H_0




    \end{equation}
     for all $t \in [0,T_2]$ implying that the condition \eqref{eq:assump_eta1_v1_d_2_part2} holds.   Then, using \eqref{eq:gronwall_wb}, the Cauchy-Schwarz inequality in time, and  the claim \eqref{Apriori}  yields
    \[
    A(t)
  \leq 4c_2 \frac{H_0}{h_0} A_0
  \mathrm{e}^{c H_0 \epsilon T_2^\frac{1}{2}\lVert\mathcal{P}\rVert_{L^2(0,T_2)}} ,
\]
where $c_2>0$ is the constant in \eqref{eq:gronwall_wb} and $\mathcal{P}(t) = \lVert\nabla \eta(t)\rVert_{L^\infty_x} +\lVert\nabla \mathbf{v}(t)\rVert_{L^\infty_x}  + \lVert\mathcal{T}_{\mu}^{-\frac{1}{2}}(D)\nabla \mathbf{v}(t)\rVert_{L^\infty_x}$.
 From \eqref{eq:est_eta_desired_Dhalf_d_2} and the assumption $T_2 < \Tilde{T}\leq T_1$, it follows that, if $s > \frac{9}{4}$, then
\begin{align*}
     \epsilon  T_2^\frac{1}{2} \lVert\mathcal{P}\rVert_{L^2(0,T_2)} &\lesssim  \epsilon
  \mu^{(-\frac{1}{6})^+} T_2^{\frac{2}{3}^+}\lVertA\rVert_{L^\infty(0,T_2)}^{\frac{1}{2}}
  + \epsilon^2  \mu^{(-\frac{1}{3})^+} T_2^{\frac{4}{3}^+} \lVertA\rVert_{L^\infty(0,T_2)} \\
  &\lesssim  \epsilon
  \mu^{(-\frac{1}{6})^+} T_1^{\frac{2}{3}^+} \sqrt{\frac{H_0}{h_0} A_0}
  +  \epsilon^2  \mu^{(-\frac{1}{3})^+} T_1^{\frac{4}{3}^+}  \frac{H_0}{h_0} A_0\\
  &=: \delta + \delta^2,
\end{align*}
where 
\begin{align}\label{eq:delta}
    \delta = c \epsilon \mu^{(-\frac{1}{6})^+} T_1^{\frac{2}{3}^+} \sqrt{\frac{H_0}{h_0} A_0}.
\end{align}
Gathering the above, we have
\begin{equation}\label{A-est}
    A(t) \le 4c_2\frac{H_0}{h_0} A_0 \mathrm{e}^{ \delta + \delta^2}
\end{equation}
for all $t\in [0,T_2]$. We choose $T_1 > 0$  so small that
\begin{equation}\label{delta-condition}
4 c \delta \leq  \frac{4 c H_0}{h_0} \delta < \frac{\log 2}{2},
\end{equation}
that is, 
\begin{align*}
     \frac{ 5c H_0}{h_0} c \epsilon \mu^{(-\frac{1}{6})^+} T_1^{\frac{2}{3}^+} \sqrt{ \frac{H_0}{h_0} A_0} < \frac{\log 2}{2},
\end{align*}
which is the same as \eqref{eq:def_T_0_d_2}. We remark that \eqref{delta-condition} implies $\delta < 1$, so that $\delta+\delta^2 < 2\delta$. This gives us 
\begin{align*}
      A(t) \le 8c_2\frac{H_0}{h_0} A_0 
\end{align*}
for all $t\in [0,T_2]$ implying
\begin{align*}
     \lVert(\eta,\mathbf{v})(t)\rVert_{V^s_\mu} \leq 3\sqrt{c_2\frac{H_0}{h_0}}\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu}.
\end{align*}
Consequently, we have from the blow-up alternative \eqref{eq:BA_d2} that $T_2< T^\ast$.                                                                       
From \eqref{eq:BA_d2}, it follows that the solution $(\eta,\mathbf{v})$ is continuous for $t\in [0,T^\ast)$. Thus, there exists a time $\tau \in [\Tilde{T},T^\ast)$ such that 
    \begin{align*}
        \lVert(\eta,\mathbf{v})(\tau)\rVert_{V^s_\mu} \leq 4  \sqrt{c_2\frac{H_0}{h_0}}\lVert(\eta_0,\mathbf{v}_0)\rVert_{V^s_\mu},
    \end{align*}
    which contradicts with the definition of $\Tilde{T}$ \eqref{eq:T_tilde_nu_d_2}. Hence, $T_1 < \Tilde{T}$, where $T_1$ is as seen in \eqref{eq:def_T_0_d_2}.
    \subsubsection*{\underline{Proof of the claim \eqref{Apriori}}}
    We start by verifying the last inequality of \eqref{Apriori}. From the fundamental theorem of calculus  and H\"{o}lder's inequality in time, we have that
    \begin{align*}
      H(t)  =  1+ \epsilon\lVert(\eta,\mathbf{v})(t)\rVert_{L^\infty_x \times L^\infty_x} &\leq  H_0 +  \epsilon T_2^\frac{1}{2} \Big(
        \lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x} + 
        \lVert\partial_t\mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}\Big). 
    \end{align*}
      From \eqref{eq:compact_eq_d_2}, Proposition \ref{prop:boundedness_eta_v_d_2}, and $T_2<\Tilde{T}$, we obtain
      \begin{align*}
          \epsilon T_2^\frac{1}{2} \lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x} &\leq \epsilon T_2^\frac{1}{2}  \Big(\lVert\nabla \cdot \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x} + \epsilon  \lVert\nabla \eta\rVert_{L^2_{T_2} L^\infty_x}\lVert\mathbf{v}\rVert_{L^\infty_{T_2} L^\infty_x}
      + \epsilon   \lVert\nabla \cdot \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}\lVert\eta\rVert_{L^\infty_{T_2} L^\infty_x}\Big) \\
      &\leq \epsilon T_2^\frac{1}{2} \lVertH\rVert_{L^\infty(0,T_2)}\lVert\mathcal{P}\rVert_{L^2(0,T_2)}\\
      &\leq 2\lVertH\rVert_{L^\infty(0,T_2)} \delta
      \end{align*}
       for $s>\frac{9}{4}$,    where $\delta$ is defined in \eqref{eq:delta}. Next, \eqref{eq:compact_eq_d_2} and 
    \begin{align*}
        (\mathbf{v} \cdot \nabla)\mathbf{v} = (v_1\partial_{x_1} v_1 + v_2 \partial_{x_2}v_1, v_1\partial_{x_1} v_2 + v_2 \partial_{x_2}v_2)^\mathrm{T}
    \end{align*}
    yields
    \begin{align*}
        \epsilon T_2^\frac{1}{2} \lVert\partial_t\mathbf{v}\rVert_{L^2_{T_2} L^\infty_x} &\leq \lVert\mathcal{T}_\mu(D)\nabla \eta\rVert_{L^2_{T_2} L^\infty_x} +  \epsilon \lVert(\mathbf{v}\cdot\nabla) \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}
        \\
        &\leq  \lVertH\rVert_{L^\infty(0,T_2)}\Big( \lVert\mathcal{T}_\mu(D)\nabla \eta\rVert_{L^2_{T_2} L^\infty_x} +  \lVert\nabla \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}\Big).
    \end{align*}
    The first term can be estimated by slightly modifying the proof of $\lVert\nabla \eta\rVert_{L^2_{T_2} L^\infty_x}$ in Proposition \ref{prop:boundedness_eta_v_d_2}, where one has to utilize \eqref{eq:est_on_tilbert}. Then from Proposition \ref{prop:boundedness_eta_v_d_2}, we obtain
    \begin{align*}
       \epsilon T_2^\frac{1}{2} \lVert\partial_t\mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}  &\leq   2\lVertH\rVert_{L^\infty(0,T_2)} \delta
    \end{align*} 
     for $s>\frac{9}{4}$.    Gathering the above calculations gives us
    \begin{align*}
        (1-4\delta) \lVertH\rVert_{L^\infty(0,T_2)} \leq H_0,
    \end{align*}
    which requires
        \begin{align*}
         4  \delta < \frac12,
     \end{align*}
     but this is satisfied due to \eqref{delta-condition}.
     \\
    \indent 
     Lastly, we will verify that $\eta$ satisfies the non-cavitation condition. From the fundamental theorem of calculus, the non-cavitation condition on $\eta_0$ \eqref{eq:noncav}, and H\"{o}lder's inequality, we obtain
    \begin{align*}                                 
        1+ \epsilon\eta(x,t) = 1 + \epsilon \eta_0+ \epsilon \int_0^t \partial_t\eta(x,s) \:\mathrm{d} s  \geq  h_0 - \epsilon T_2^{\frac{1}{2}} \lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x}
    \end{align*}
    for all $(x,t)\in \mathbb{R}^2 \times [0,T_2]$. It is enough to prove that
    \begin{align*}
       \epsilon T_2^{\frac{1}{2}} \lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x}  \leq \frac{h_0}{2}.
    \end{align*}
    From the first equation in \eqref{eq:whitham_boussinesq_d2}, H\"{o}lder's inequality, the second inequality in \eqref{Apriori} (verified above), Proposition \ref{prop:boundedness_eta_v_d_2}, and the assumption $T_2<\Tilde{T}\leq T_1$, we obtain
    \begin{align*}                                    
        \epsilon T_2^{\frac{1}{2}}\lVert\partial_t\eta\rVert_{L^2_{T_2} L^\infty_x} &\leq \lVert\nabla \cdot \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x} + \epsilon \lVert\nabla \eta\rVert_{L^2_{T_2} L^\infty_x}\lVert\mathbf{v}\rVert_{L^\infty_{T_2} L^\infty_x}
      + \epsilon \lVert\nabla \cdot \mathbf{v}\rVert_{L^2_{T_2} L^\infty_x}\lVert\eta\rVert_{L^\infty_{T_2} L^\infty_x} \\ \notag
        &\leq 2H_0  \epsilon T_2^{\frac{1}{2}}\lVert\mathcal{P}\rVert_{L^2(0,T_2)} \\ \notag
        &\leq 4cH_0 \delta
    \end{align*}
     for $s>\frac{9}{4}$. So, we need 
     \begin{align*}
         4c \frac{H_0}{h_0} \delta < \frac12
     \end{align*}
     to conclude, which holds by \eqref{delta-condition}.

    \renewcommand$\overset{\text{Lemma \ref{lem:bootstrap_wb}}}{\ensuremath{\Box}}${$\overset{\text{Lemma \ref{lem:bootstrap_wb}}}{\ensuremath{\Box}}$}
